window.QB_TKP_B8 = [
{id:"TKP-1081", q:"Banjir besar melanda kecamatan Anda. Ratusan warga mengantre di posko untuk meminta surat keterangan terdampak bencana sebagai syarat klaim bantuan. Antrean membludak dan warga mulai resah. Tindakan Anda?", opts:[{t:"Membuka loket tambahan, membagi antrean per RT, dan memprioritaskan lansia, ibu hamil, serta difabel sambil tetap melayani semua", s:5},{t:"Tetap melayani di satu loket dengan tertib sesuai urutan kedatangan", s:4},{t:"Meminta warga kembali besok karena petugas kewalahan", s:3},{t:"Melayani hanya warga yang membawa fotokopi KTP lengkap, sisanya disuruh pulang", s:2},{t:"Menutup loket lebih awal agar petugas bisa istirahat", s:1}], ex:"Skor 5 terbaik: menambah kapasitas layanan, mengatur antrean adil, dan memprioritaskan kelompok rentan — pelayanan adaptif dan berorientasi pada warga."},
{id:"TKP-1082", q:"Gempa merusak sebagian kantor kelurahan sehingga pelayanan administrasi tidak bisa dilakukan di ruang biasa. Warga tetap berdatangan membutuhkan layanan. Apa yang Anda lakukan?", opts:[{t:"Mendirikan tenda layanan darurat di halaman kantor dengan pembagian tugas jelas agar pelayanan tetap berjalan", s:5},{t:"Memindahkan pelayanan ke balai warga terdekat yang masih aman", s:4},{t:"Melayani warga seadanya di puing kantor sambil menunggu perbaikan", s:3},{t:"Menunda semua pelayanan sampai gedung diperbaiki", s:2},{t:"Menyuruh warga mengurus ke kelurahan lain tanpa pendampingan", s:1}], ex:"Skor 5 terbaik: pelayanan publik tidak boleh berhenti karena bencana; tenda darurat menunjukkan kesiapan dan tanggung jawab."},
{id:"TKP-1083", q:"Kebakaran menghanguskan satu permukiman padat. Puluhan warga kehilangan seluruh dokumen kependudukan (KTP, KK, akta). Mereka butuh dokumen pengganti untuk mengakses bantuan. Sikap Anda?", opts:[{t:"Membuka layanan jemput bola di posko pengungsian: perekaman dan penerbitan dokumen pengganti dengan prosedur yang disederhanakan sesuai aturan", s:5},{t:"Melayani penggantian dokumen di kantor dengan antrean khusus korban kebakaran", s:4},{t:"Melayani seperti biasa, korban kebakaran antre bersama warga lain", s:3},{t:"Meminta warga mengurus surat kehilangan ke polisi dulu tanpa bantuan pendampingan", s:2},{t:"Menolak melayani karena data kependudukan mereka ikut terbakar", s:1}], ex:"Skor 5 terbaik: proaktif mendatangi korban (jemput bola) dan menyederhanakan prosedur dalam koridor aturan — pelayanan prima bagi yang paling membutuhkan."},
{id:"TKP-1084", q:"Longsor menutup satu-satunya akses jalan ke sebuah desa. Bantuan logistik tertahan dan warga desa mulai kekurangan bahan pangan. Anda bagian dari tim distribusi. Apa langkah Anda?", opts:[{t:"Segera berkoordinasi dengan BPBD/TNI untuk membuka jalur alternatif atau pengiriman via jalur darurat, sambil menginventarisasi kebutuhan mendesak warga", s:5},{t:"Menunggu jalan dibuka oleh dinas PU sebelum menyalurkan bantuan", s:4},{t:"Menitipkan bantuan ke desa tetangga agar diteruskan seadanya", s:3},{t:"Menunda penyaluran sampai kondisi benar-benar aman tanpa mencari alternatif", s:2},{t:"Membatalkan penyaluran ke desa tersebut dan mengalihkan bantuan ke wilayah yang mudah dijangkau", s:1}], ex:"Skor 5 terbaik: mencari solusi alternatif lewat koordinasi lintas instansi alih-alih pasif menunggu — berorientasi hasil bagi warga terisolir."},
{id:"TKP-1085", q:"Anda ditugaskan mengelola pendaftaran pengungsi di posko. Data yang masuk kacau: ada yang terdaftar dua kali, ada yang belum terdata sama sekali. Bagaimana Anda menanganinya?", opts:[{t:"Membuat sistem pendataan ulang yang rapi (nomor registrasi per KK), memverifikasi satu per satu, dan mempublikasikan alur pendaftaran agar transparan", s:5},{t:"Mendata ulang semua pengungsi dengan formulir sederhana", s:4},{t:"Memakai data yang ada saja meski tidak akurat", s:3},{t:"Meminta setiap RT mendata warganya sendiri tanpa verifikasi", s:2},{t:"Membiarkan kekacauan data karena situasi darurat", s:1}], ex:"Skor 5 terbaik: data akurat adalah fondasi distribusi bantuan yang adil; pendataan ulang sistematis menunjukkan akuntabilitas."},
{id:"TKP-1086", q:"Seorang lansia sebatang kara ditemukan lemas di rumahnya yang terendam banjir. Ia tidak punya keluarga dan menolak dievakuasi karena takut kehilangan harta bendanya. Tindakan Anda?", opts:[{t:"Membujuk dengan sabar, menjelaskan keselamatannya yang utama, menawarkan penitipan barang berharga, dan mengantarnya ke posko dengan pendampingan", s:5},{t:"Mengajak tokoh masyarakat yang dikenalnya untuk membujuk", s:4},{t:"Meninggalkannya setelah ia menolak, karena itu pilihannya", s:3},{t:"Memaksanya dievakuasi dengan cara kasar agar cepat", s:2},{t:"Mengabaikannya karena masih banyak warga lain yang butuh bantuan", s:1}], ex:"Skor 5 terbaik: persuasif, empatik, dan solutif (tawaran penitipan barang) — menghormati otonomi lansia sekaligus menjamin keselamatannya."},
{id:"TKP-1087", q:"Saat evakuasi banjir, seorang anak kecil terpisah dari orang tuanya dan menangis ketakutan di posko. Tidak ada yang mengenalnya. Apa yang Anda lakukan?", opts:[{t:"Menenangkannya, mencatat ciri-ciri dan namanya, mengumumkan ke seluruh posko dan grup koordinasi, serta menemaninya sampai bertemu keluarga", s:5},{t:"Menitipkannya ke petugas posko sambil mengumumkan pencariannya", s:4},{t:"Mengumumkannya sekali lewat pengeras suara lalu kembali bertugas", s:3},{t:"Menyuruhnya menunggu di sudut posko sampai orang tuanya datang", s:2},{t:"Menganggap orang tuanya pasti segera datang dan tidak melakukan apa-apa", s:1}], ex:"Skor 5 terbaik: perlindungan anak adalah prioritas; aktif mencari keluarga dan mendampingi anak menunjukkan tanggung jawab penuh."},
{id:"TKP-1088", q:"Sebagian warga menolak dievakuasi dari zona bahaya longsor dengan alasan menjaga rumah dan ternak. Hujan deras diprediksi berlanjut. Sikap Anda sebagai petugas?", opts:[{t:"Terus melakukan pendekatan persuasif bersama tokoh masyarakat, menjelaskan risiko nyata, dan menawarkan solusi penitipan ternak serta penjagaan rumah bergiliran", s:5},{t:"Memberi peringatan resmi tentang bahaya dan meminta tanda tangan penolakan evakuasi", s:4},{t:"Membiarkan mereka tinggal karena itu hak mereka", s:3},{t:"Mengancam akan mencabut bantuan jika tidak mau dievakuasi", s:2},{t:"Meninggalkan mereka dan fokus ke warga yang mau dievakuasi", s:1}], ex:"Skor 5 terbaik: keselamatan jiwa adalah yang utama; pendekatan persuasif dengan solusi konkret (penitipan ternak) mengatasi akar keberatan warga."},
{id:"TKP-1089", q:"Bantuan logistik menumpuk di gudang posko sementara distribusi ke pengungsi lambat karena kekurangan tenaga sortir. Warga mulai mengeluh. Apa langkah Anda?", opts:[{t:"Mengorganisir relawan dan warga untuk gotong royong menyortir dan mendistribusikan bantuan dengan sistem antrean yang tertib", s:5},{t:"Meminta tambahan personel dari dinas terkait", s:4},{t:"Mendistribusikan seadanya sesuai kemampuan petugas yang ada", s:3},{t:"Menyuruh warga mengambil sendiri ke gudang tanpa pengaturan", s:2},{t:"Membiarkan bantuan menumpuk sampai ada instruksi atasan", s:1}], ex:"Skor 5 terbaik: inisiatif menggerakkan sumber daya yang ada (relawan, warga) untuk mempercepat distribusi — solutif dan kolaboratif."},
{id:"TKP-1090", q:"Hasil verifikasi menunjukkan data penerima bansos banyak yang tidak akurat: ada yang sudah meninggal, pindah domisili, bahkan sudah mampu. Sementara warga miskin yang berhak belum terdata. Tindakan Anda?", opts:[{t:"Mengusulkan pemutakhiran data (musyawarah desa/kelurahan) secara transparan, mencoret yang tidak berhak, dan mengusulkan yang berhak sesuai mekanisme resmi", s:5},{t:"Melaporkan temuan ke atasan untuk ditindaklanjuti", s:4},{t:"Tetap menyalurkan sesuai data lama agar cepat", s:3},{t:"Mencoret sepihak nama yang dicurigai tanpa verifikasi", s:2},{t:"Membiarkan karena pemutakhiran data bukan tugas Anda", s:1}], ex:"Skor 5 terbaik: ketepatan sasaran bansos adalah keadilan; pemutakhiran melalui mekanisme resmi yang transparan adalah langkah akuntabel."},
{id:"TKP-1091", q:"Banyak keluarga penerima PKH tidak tahu jadwal pencairan bantuan tahap berjalan sehingga antrean di bank/agen menumpuk di hari yang salah. Sebagai pendamping sosial, apa yang Anda lakukan?", opts:[{t:"Menyusun dan menyebarkan jadwal pencairan per kelompok melalui RT, grup WA, dan papan pengumuman jauh sebelum hari-H", s:5},{t:"Memberi tahu jadwal saat ada yang bertanya", s:4},{t:"Menempel jadwal di papan pengumuman kantor saja", s:3},{t:"Menyuruh KPM menanyakan sendiri ke bank", s:2},{t:"Tidak melakukan apa-apa, itu urusan bank penyalur", s:1}], ex:"Skor 5 terbaik: komunikasi proaktif multi-saluran mencegah penumpukan dan memudahkan KPM — pelayanan yang antisipatif."},
{id:"TKP-1092", q:"Seorang warga yang tergolong mampu protes keras di kantor karena namanya tidak masuk daftar penerima bansos, sementara tetangganya yang ia anggap lebih mampu justru menerima. Bagaimana Anda menangani?", opts:[{t:"Menerima protesnya dengan tenang, menjelaskan kriteria dan mekanisme penetapan penerima, serta mengarahkan ke jalur sanggah/pendataan ulang resmi", s:5},{t:"Menjelaskan kriteria penerima dengan sabar", s:4},{t:"Menyuruhnya bertanya ke RT yang mendata", s:3},{t:"Mengabaikan protesnya karena datanya sudah final", s:2},{t:"Membentaknya agar tidak membuat keributan di kantor", s:1}], ex:"Skor 5 terbaik: tetap tenang, transparan soal kriteria, dan memberi saluran resmi untuk keberatan — menghormati warga tanpa melanggar aturan."},
{id:"TKP-1093", q:"Anda ditugaskan menyalurkan sembako ke dusun terisolir pasca-banjir. Kendaraan tidak bisa masuk 3 km terakhir karena jalan rusak. Apa yang Anda lakukan?", opts:[{t:"Berkoordinasi dengan warga dan relawan untuk memikul/mengangkut bantuan tahap demi tahap hingga sampai, memastikan tidak ada yang tertinggal", s:5},{t:"Mencari kendaraan roda dua atau gerobak untuk mengangkut bertahap", s:4},{t:"Menitipkan bantuan di titik terdekat dan meminta warga mengambil sendiri", s:3},{t:"Menunda penyaluran sampai jalan bisa dilalui kendaraan", s:2},{t:"Mengembalikan bantuan ke gudang karena tidak bisa diantar", s:1}], ex:"Skor 5 terbaik: keterbatasan akses bukan alasan berhenti; gotong royong mengantar hingga titik terakhir menjamin bantuan sampai ke yang berhak."},
{id:"TKP-1094", q:"Di posko pengungsian ada beberapa penyandang disabilitas yang kesulitan mengakses MCK dan tempat tidur yang tersedia. Tidak ada fasilitas khusus. Tindakan Anda?", opts:[{t:"Segera mengatur area khusus yang mudah diakses, meminta bantuan relawan mendampingi, dan mengusulkan pengadaan fasilitas darurat yang ramah disabilitas", s:5},{t:"Memindahkan mereka ke tenda yang paling dekat dengan MCK", s:4},{t:"Meminta keluarga mereka membantu kebutuhannya", s:3},{t:"Menyarankan mereka pulang ke rumah saudara yang lebih layak", s:2},{t:"Menganggap kondisi darurat memang tidak bisa ideal untuk semua", s:1}], ex:"Skor 5 terbaik: kelompok rentan harus diprioritaskan bahkan dalam keterbatasan; penyesuaian fasilitas menunjukkan pelayanan inklusif."},
{id:"TKP-1095", q:"Seorang ibu hamil di posko pengungsian mengeluh kontraksi. Puskesmas terdekat kebanjiran dan ambulans sulit masuk. Apa prioritas tindakan Anda?", opts:[{t:"Segera menghubungi bidan/dokter terdekat, menyiapkan ruang privat darurat di posko, dan mengupayakan evakuasi medis dengan segala sarana yang ada", s:5},{t:"Menghubungi dinas kesehatan untuk meminta bantuan medis", s:4},{t:"Menyuruh keluarganya membawa sendiri ke rumah sakit", s:3},{t:"Menunggu sampai akses jalan membaik", s:2},{t:"Menganggap itu bukan tanggung jawab tim posko", s:1}], ex:"Skor 5 terbaik: nyawa ibu dan bayi adalah prioritas mutlak; mengerahkan semua sumber daya yang ada mencerminkan keberpihakan pada keselamatan."},
{id:"TKP-1096", q:"Di pengungsian mulai banyak anak yang diare dan batuk pilek. Diduga dari air minum dan kepadatan hunian. Sebagai koordinator posko, apa langkah Anda?", opts:[{t:"Segera berkoordinasi dengan dinas kesehatan untuk pemeriksaan, memastikan air minum aman, memperbaiki sanitasi, dan mengatur ulang kepadatan tenda", s:5},{t:"Membagikan obat seadanya dari kotak P3K posko", s:4},{t:"Mengimbau warga menjaga kebersihan", s:3},{t:"Menunggu ada yang sakit parah baru bertindak", s:2},{t:"Menganggap sakit ringan di pengungsian hal biasa", s:1}], ex:"Skor 5 terbaik: respons cepat berbasis koordinasi ahli (dinkes) plus perbaikan akar masalah (air, sanitasi, kepadatan) — pencegahan sistematis."},
{id:"TKP-1097", q:"Persediaan air bersih di posko pengungsian habis, sementara bantuan berikutnya baru datang besok. Ratusan pengungsi butuh air untuk minum dan memasak. Apa yang Anda lakukan?", opts:[{t:"Segera menghubungi PDAM/dinas terkait dan relawan untuk pengiriman darurat, sambil mengatur pembagian air sisa secara adil dan transparan", s:5},{t:"Membeli air kemasan dengan dana darurat posko", s:4},{t:"Membagikan air sisa seadanya tanpa pengaturan", s:3},{t:"Menyuruh warga mencari air sendiri", s:2},{t:"Menunggu bantuan besok tanpa tindakan", s:1}], ex:"Skor 5 terbaik: kebutuhan dasar tidak bisa ditunda; kombinasi solusi darurat dan distribusi adil menunjukkan kepemimpinan tanggap."},
{id:"TKP-1098", q:"MCK di posko pengungsian rusak dan kotor, antrean panjang, sebagian pengungsi buang air sembarangan. Kondisi ini berisiko menimbulkan penyakit. Tindakan Anda?", opts:[{t:"Segera memperbaiki dan membersihkan MCK dengan mengerahkan petugas/relawan, membuat jadwal piket kebersihan, dan menyediakan MCK darurat tambahan", s:5},{t:"Menyewa toilet portable darurat", s:4},{t:"Mengimbau warga menjaga kebersihan MCK", s:3},{t:"Menutup MCK yang rusak dan membiarkan antrean di satu titik", s:2},{t:"Membiarkan karena perbaikan butuh anggaran", s:1}], ex:"Skor 5 terbaik: sanitasi adalah kebutuhan dasar pengungsi; tindakan cepat plus sistem piket mencegah masalah berulang."},
{id:"TKP-1099", q:"Listrik padam di posko pengungsian pada malam hari. Pengungsi panik, anak-anak menangis, dan keamanan barang menjadi kekhawatiran. Apa yang Anda lakukan?", opts:[{t:"Segera menyalakan genset/lampu darurat, menenangkan pengungsi lewat pengumuman, dan mengatur ronda keamanan malam", s:5},{t:"Membagikan lilin dan senter seadanya", s:4},{t:"Menyuruh warga tetap tenang dan menunggu listrik menyala", s:3},{t:"Menghubungi PLN dan menunggu tanpa tindakan lain", s:2},{t:"Ikut panik dan tidak tahu harus berbuat apa", s:1}], ex:"Skor 5 terbaik: mengatasi kegelapan (penerangan darurat), kepanikan (komunikasi menenangkan), dan keamanan sekaligus — respons menyeluruh."},
{id:"TKP-1100", q:"Beberapa pengungsi melaporkan barang berharganya hilang di posko yang padat dan terbuka. Kecurigaan antar-pengungsi mulai muncul. Bagaimana Anda menangani?", opts:[{t:"Membuat sistem penitipan barang berharga yang aman, mengatur petugas keamanan/ronda, dan menindaklanjuti laporan kehilangan secara serius", s:5},{t:"Mengimbau semua pengungsi menjaga barang masing-masing", s:4},{t:"Menyarankan korban melapor ke polisi", s:3},{t:"Menganggap kehilangan di pengungsian risiko masing-masing", s:2},{t:"Menuduh pihak tertentu tanpa bukti", s:1}], ex:"Skor 5 terbaik: sistem penitipan mencegah kejadian berulang dan penindaklanjutan serius memulihkan rasa aman — bukan sekadar imbauan."},
{id:"TKP-1101", q:"Warga melaporkan ternak sapi dan kambing mereka terjebak di kandang yang terendam banjir. Mereka khawatir ternak mati karena itu sumber penghidupan utama. Anda petugas lapangan. Apa yang Anda lakukan?", opts:[{t:"Berkoordinasi dengan tim dan warga untuk mengevakuasi ternak ke tempat yang aman, karena ternak adalah aset penghidupan warga", s:5},{t:"Menyarankan warga mengevakuasi ternak sendiri dengan bantuan tetangga", s:4},{t:"Mencatat laporan warga untuk ditindaklanjuti nanti", s:3},{t:"Menyuruh warga fokus menyelamatkan diri, ternak biar saja", s:2},{t:"Mengabaikan laporan karena prioritas hanya manusia", s:1}], ex:"Skor 5 terbaik: bagi warga, ternak adalah mata pencaharian; mengevakuasinya melindungi ekonomi keluarga pasca-bencana."},
{id:"TKP-1102", q:"Sekolah di wilayah bencana rusak berat. Ratusan anak tidak bisa bersekolah dan mulai berkeliaran tanpa kegiatan di pengungsian. Sebagai aparatur, apa inisiatif Anda?", opts:[{t:"Berkoordinasi dengan dinas pendidikan untuk membuka sekolah darurat di tenda posko dengan guru relawan dan materi sederhana", s:5},{t:"Mengumpulkan anak-anak untuk kegiatan belajar bersama seadanya", s:4},{t:"Menunggu sekolah diperbaiki agar kegiatan belajar normal kembali", s:3},{t:"Membiarkan anak-anak bermain sendiri di pengungsian", s:2},{t:"Menganggap pendidikan bukan prioritas saat darurat", s:1}], ex:"Skor 5 terbaik: hak pendidikan anak tetap berjalan lewat sekolah darurat; inisiatif lintas dinas menunjukkan kepedulian menyeluruh."},
{id:"TKP-1103", q:"Banyak anak di pengungsian menunjukkan trauma: murung, mudah kaget, dan mimpi buruk setelah gempa. Orang tua mereka bingung menghadapinya. Apa yang Anda lakukan?", opts:[{t:"Berkoordinasi dengan psikolog/relawan untuk layanan dukungan psikososial anak (bermain, menggambar, konseling) dan mengedukasi orang tua", s:5},{t:"Mengadakan kegiatan bermain bersama untuk menghibur anak-anak", s:4},{t:"Menyarankan orang tua bersabar, trauma akan hilang sendiri", s:3},{t:"Menganggap anak-anak akan lupa sendiri seiring waktu", s:2},{t:"Mengabaikan karena tidak ada korban luka fisik", s:1}], ex:"Skor 5 terbaik: trauma psikis sama pentingnya dengan luka fisik; dukungan psikososial profesional adalah penanganan yang tepat."},
{id:"TKP-1104", q:"Donasi pakaian bekas menumpuk di posko tanpa disortir: campur aduk pakaian dewasa, anak, bahkan yang rusak. Pengungsi kesulitan mencari yang sesuai. Tindakan Anda?", opts:[{t:"Mengorganisir relawan menyortir pakaian per kategori dan ukuran, membuang yang rusak, lalu membuka 'toko gratis' yang tertata", s:5},{t:"Menyortir seadanya bersama petugas posko", s:4},{t:"Membiarkan pengungsi memilih sendiri dari tumpukan", s:3},{t:"Membagikan karung-karung pakaian tanpa dibuka ke tiap tenda", s:2},{t:"Membiarkan tumpukan karena keterbatasan tenaga", s:1}], ex:"Skor 5 terbaik: donasi yang tertata menghormati martabat penerima; pengorganisasian sistematis mengubah tumpukan jadi layanan."},
{id:"TKP-1105", q:"Pembagian bantuan tunai di posko menimbulkan antrean panjang di bawah terik matahari. Banyak lansia dan ibu menyusui ikut antre berjam-jam. Apa solusi Anda?", opts:[{t:"Membuat jalur antrean prioritas untuk lansia, ibu hamil/menyusui, dan difabel, menambah loket, serta menyediakan tempat duduk dan air minum", s:5},{t:"Membagi jadwal pencairan per hari agar antrean terpecah", s:4},{t:"Meminta warga antre dengan tertib dan bersabar", s:3},{t:"Mempercepat proses dengan mengurangi verifikasi", s:2},{t:"Membiarkan antrean apa adanya", s:1}], ex:"Skor 5 terbaik: mengatur ulang sistem antrean yang manusiawi — prioritas kelompok rentan plus kenyamanan dasar."},
{id:"TKP-1106", q:"Seorang korban kebakaran kehilangan KTP dan tidak terdaftar sebagai penerima bantuan karena namanya tidak ada di data. Ia menangis karena merasa tidak diperhatikan. Bagaimana Anda menangani?", opts:[{t:"Memverifikasi identitasnya melalui keterangan RT/saksi dan data kependudukan, lalu memasukkannya ke daftar penerima susulan sesuai prosedur", s:5},{t:"Mencatatnya untuk didata pada pendataan berikutnya", s:4},{t:"Menyuruhnya mengurus KTP baru dulu ke Dukcapil", s:3},{t:"Menolak karena data penerima sudah final", s:2},{t:"Menyuruhnya pulang dan tidak kembali sebelum punya KTP", s:1}], ex:"Skor 5 terbaik: verifikasi alternatif (RT/saksi) memungkinkan korban tetap terlayani tanpa melanggar prinsip akuntabilitas data."},
{id:"TKP-1107", q:"Ketua RT melaporkan ada 15 KK korban banjir di wilayahnya yang belum terdata sebagai penerima bantuan karena saat pendataan mereka mengungsi ke luar daerah. Sikap Anda?", opts:[{t:"Melakukan verifikasi lapangan ke alamat mereka dan memasukkan yang terbukti korban ke daftar susulan resmi", s:5},{t:"Meminta RT membuat surat keterangan untuk tiap KK", s:4},{t:"Menunggu pendataan tahap berikutnya", s:3},{t:"Menolak karena pendataan sudah ditutup", s:2},{t:"Mengabaikan laporan RT tersebut", s:1}], ex:"Skor 5 terbaik: warga yang mengungsi ke luar daerah tetap korban; verifikasi dan pendataan susulan menegakkan keadilan."},
{id:"TKP-1108", q:"Pengungsi dari daerah lain datang ke wilayah Anda tanpa membawa identitas sama sekali. Mereka butuh bantuan mendesak namun prosedur mensyaratkan data diri. Apa yang Anda lakukan?", opts:[{t:"Memberikan bantuan darurat terlebih dahulu sambil melakukan pendataan identitas melalui wawancara dan koordinasi dengan daerah asal", s:5},{t:"Mendata seadanya berdasarkan pengakuan mereka lalu memberi bantuan", s:4},{t:"Memberi bantuan sekali saja sambil menunggu identitas", s:3},{t:"Menolak memberi bantuan sampai identitas jelas", s:2},{t:"Mengusir mereka karena bukan warga wilayah Anda", s:1}], ex:"Skor 5 terbaik: kebutuhan darurat didahulukan (prinsip kemanusiaan), pendataan menyusul lewat koordinasi — tidak birokratis kaku."},
{id:"TKP-1109", q:"Terjadi keributan antar-pengungsi karena merasa pembagian sembako tidak adil: ada yang dapat dua kali, ada yang belum dapat sama sekali. Situasi memanas. Tindakan Anda?", opts:[{t:"Menenangkan semua pihak, menjelaskan sistem pembagian per KK yang transparan, memperbaiki data, dan memastikan yang belum dapat segera terlayani", s:5},{t:"Menghentikan pembagian sementara sampai situasi tenang", s:4},{t:"Membagikan sisa sembako seadanya agar keributan reda", s:3},{t:"Memihak kelompok yang paling keras protes agar cepat selesai", s:2},{t:"Meninggalkan lokasi dan membiarkan mereka menyelesaikan sendiri", s:1}], ex:"Skor 5 terbaik: transparansi sistem + perbaikan data + pemenuhan yang tertinggal menyelesaikan akar masalah, bukan sekadar meredam."},
{id:"TKP-1110", q:"Sejumlah LSM dan komunitas ingin menyalurkan bantuan langsung ke pengungsian tanpa berkoordinasi dengan posko resmi. Berisiko terjadi penumpukan di satu titik dan kekosongan di titik lain. Sikap Anda?", opts:[{t:"Menyambut baik dan mengarahkan mereka ke sistem koordinasi posko agar bantuan terdistribusi merata sesuai kebutuhan riil", s:5},{t:"Mempersilakan mereka menyalurkan sendiri", s:4},{t:"Meminta mereka menyerahkan semua bantuan ke posko", s:3},{t:"Melarang mereka masuk ke area pengungsian", s:2},{t:"Mengabaikan karena bantuan tambahan selalu baik", s:1}], ex:"Skor 5 terbaik: mengarahkan (bukan menolak/melarang) niat baik ke koordinasi resmi — memaksimalkan manfaat bantuan."},
{id:"TKP-1111", q:"Beberapa jurnalis ingin meliput dan memotret dari dekat anak-anak pengungsi yang trauma untuk kebutuhan berita. Orang tua keberatan. Bagaimana Anda menangani?", opts:[{t:"Menjelaskan etika peliputan kepada jurnalis, mengarahkan ke area dan narasumber yang bersedia, serta melindungi privasi dan martabat pengungsi", s:5},{t:"Meminta jurnalis meminta izin dulu ke orang tua", s:4},{t:"Mempersilakan meliput karena itu hak pers", s:3},{t:"Melarang total semua peliputan di posko", s:2},{t:"Membiarkan jurnalis bekerja tanpa pengaturan", s:1}], ex:"Skor 5 terbaik: menyeimbangkan keterbukaan informasi dan perlindungan korban — pengaturan yang etis, bukan pelarangan buta."},
{id:"TKP-1112", q:"Beredar pesan berantai bahwa bendungan di hulu akan jebol dan banjir bandang akan datang malam ini. Warga panik. Belum ada konfirmasi resmi. Apa yang Anda lakukan?", opts:[{t:"Segera mengonfirmasi ke BPBD/pengelola bendungan, lalu menyampaikan informasi resmi yang benar ke warga melalui saluran resmi untuk meredam kepanikan", s:5},{t:"Mengimbau warga tidak panik dan menunggu info resmi", s:4},{t:"Meneruskan pesan tersebut agar warga waspada", s:3},{t:"Ikut panik dan bersiap mengungsi", s:2},{t:"Mengabaikan karena menganggap itu hoaks", s:1}], ex:"Skor 5 terbaik: verifikasi cepat ke sumber berwenang lalu komunikasi resmi — memutus rantai hoaks dengan fakta."},
{id:"TKP-1113", q:"Isu gempa susulan besar beredar di pengungsian membuat warga takut kembali ke dalam tenda dan memilih tidur di lapangan terbuka yang tidak aman. Tindakan Anda?", opts:[{t:"Menyampaikan penjelasan resmi dari BMKG tentang status gempa, menenangkan warga, dan memastikan tenda darurat aman untuk ditempati", s:5},{t:"Mengimbau warga kembali ke tenda masing-masing", s:4},{t:"Membiarkan warga tidur di lapangan karena itu pilihan mereka", s:3},{t:"Ikut menyebarkan isu agar warga tetap waspada", s:2},{t:"Menganggap ketakutan warga berlebihan", s:1}], ex:"Skor 5 terbaik: informasi resmi dari otoritas (BMKG) adalah penangkal kepanikan yang tepat, disertai jaminan keamanan tenda."},
{id:"TKP-1114", q:"Ambulans yang membawa korban luka terjebak kemacetan akibat warga menonton di lokasi bencana. Kondisi korban kritis. Anda petugas di lokasi. Apa yang Anda lakukan?", opts:[{t:"Segera mengatur lalu lintas bersama petugas, membuka jalur darurat, dan meminta warga memberi jalan", s:5},{t:"Meminta warga yang menonton bubar", s:4},{t:"Mencari jalan alternatif untuk ambulans", s:3},{t:"Menunggu kemacetan terurai sendiri", s:2},{t:"Tidak melakukan apa-apa karena bukan tugas Anda", s:1}], ex:"Skor 5 terbaik: tindakan langsung membuka jalur darurat — setiap menit menentukan nyawa korban kritis."},
{id:"TKP-1115", q:"Dapur umum posko kehabisan bahan bakar untuk memasak, sementara ratusan pengungsi menunggu makan siang. Bantuan logistik berikutnya belum jelas kapan datang. Solusi Anda?", opts:[{t:"Segera mencari bahan bakar alternatif (kayu bakar, kompor cadangan, pinjam dari warga/dapur lain) sambil berkoordinasi untuk pasokan lanjutan", s:5},{t:"Membeli bahan bakar dengan dana darurat", s:4},{t:"Menunda makan siang sampai bahan bakar datang", s:3},{t:"Membagikan makanan mentah agar dimasak sendiri", s:2},{t:"Menyuruh pengungsi mencari makan sendiri", s:1}], ex:"Skor 5 terbaik: kreatif mencari solusi langsung (alternatif bahan bakar) sambil menyiapkan pasokan lanjutan — dapur umum tidak boleh berhenti."},
{id:"TKP-1116", q:"Stok obat-obatan di posko kesehatan menipis: obat diare, perban, dan obat luka hampir habis, sementara pasien terus berdatangan. Apa langkah Anda?", opts:[{t:"Segera berkoordinasi dengan dinas kesehatan/RS untuk pasokan darurat, sambil memprioritaskan obat untuk kasus paling mendesak", s:5},{t:"Membeli obat dengan dana posko seadanya", s:4},{t:"Membatasi layanan hanya untuk kasus berat", s:3},{t:"Menyuruh pasien membeli obat sendiri di apotek", s:2},{t:"Menutup posko kesehatan sementara", s:1}], ex:"Skor 5 terbaik: koordinasi pasokan darurat plus triase prioritas — layanan kesehatan tetap berjalan dengan sumber daya terbatas."},
{id:"TKP-1117", q:"Tim SAR menemukan jenazah korban longsor. Keluarga korban yang menunggu di posko mendesak proses identifikasi dipercepat dan meminta jenazah segera diserahkan. Bagaimana Anda menangani?", opts:[{t:"Menjelaskan prosedur identifikasi (DVI) dengan empati, mendampingi keluarga, dan mempercepat koordinasi tanpa melanggar prosedur", s:5},{t:"Meminta keluarga bersabar menunggu proses selesai", s:4},{t:"Menyerahkan jenazah langsung agar keluarga tenang", s:3},{t:"Menyuruh keluarga menunggu tanpa penjelasan", s:2},{t:"Mengabaikan desakan keluarga", s:1}], ex:"Skor 5 terbaik: empati + penjelasan prosedur + percepatan koordinasi — menghormati duka keluarga tanpa mengorbankan akurasi identifikasi."},
{id:"TKP-1118", q:"Keluarga korban bencana yang belum ditemukan menuntut informasi perkembangan pencarian setiap jam dan mulai menuduh tim tidak serius bekerja. Sikap Anda?", opts:[{t:"Memberikan update berkala yang jujur tentang upaya pencarian, menjelaskan kendala lapangan, dan mendampingi keluarga dengan empati", s:5},{t:"Menjelaskan bahwa tim sudah bekerja maksimal", s:4},{t:"Meminta keluarga menunggu dengan sabar", s:3},{t:"Menghindari keluarga agar tidak dituntut terus", s:2},{t:"Memarahi keluarga karena dianggap mengganggu kerja tim", s:1}], ex:"Skor 5 terbaik: komunikasi jujur dan berkala membangun kepercayaan; empati meredam tuduhan yang lahir dari kecemasan."},
{id:"TKP-1119", q:"Tanggul sungai jebol dan air terus meluap ke permukiman. Perbaikan darurat dengan karung pasir butuh keputusan cepat, tetapi atasan Anda sulit dihubungi. Apa yang Anda lakukan?", opts:[{t:"Mengambil inisiatif memimpin perbaikan darurat bersama warga dan melaporkan ke atasan segera setelahnya, karena keselamatan tidak bisa menunggu", s:5},{t:"Terus berusaha menghubungi atasan sambil menyiapkan material", s:4},{t:"Menunggu atasan bisa dihubungi sebelum bertindak", s:3},{t:"Menyuruh warga memperbaiki sendiri", s:2},{t:"Tidak berbuat apa-apa karena tidak ada perintah", s:1}], ex:"Skor 5 terbaik: dalam keadaan darurat, inisiatif menyelamatkan warga didahulukan dengan tetap melaporkan kemudian — kepemimpinan tanggap."},
{id:"TKP-1120", q:"Pasca-banjir, pemerintah akan melakukan normalisasi sungai yang mengharuskan pembongkaran sebagian rumah warga di bantaran. Warga terdampak menolak dan merasa tidak dilibatkan. Bagaimana Anda menangani?", opts:[{t:"Memfasilitasi sosialisasi dan dialog, menjelaskan program dan hak warga (ganti rugi/relokasi), serta menampung aspirasi mereka ke pengambil keputusan", s:5},{t:"Menjelaskan bahwa program sudah diputuskan pemerintah", s:4},{t:"Meminta warga menerima demi kepentingan umum", s:3},{t:"Membiarkan warga berdemo tanpa difasilitasi", s:2},{t:"Mengancam warga yang menolak dengan penertiban paksa", s:1}], ex:"Skor 5 terbaik: memfasilitasi dialog dua arah — warga mendapat penjelasan dan salurannya didengar, program tetap berjalan manusiawi."},
{id:"TKP-1121", q:"Korban banjir akan direlokasi ke hunian sementara (huntara). Sebagian warga menolak pindah karena lokasinya jauh dari tempat kerja dan sekolah anak. Bagaimana Anda menangani?", opts:[{t:"Berdialog dengan warga, menjelaskan alasan relokasi demi keselamatan, mendata kebutuhan mereka (transportasi, sekolah), dan mengupayakan solusinya", s:5},{t:"Menjelaskan bahwa huntara adalah satu-satunya pilihan yang tersedia", s:4},{t:"Memberi tenggat waktu agar warga segera pindah", s:3},{t:"Membiarkan warga tetap tinggal di lokasi berbahaya", s:2},{t:"Memaksa warga pindah dengan aparat", s:1}], ex:"Skor 5 terbaik: dialog yang mendengar keberatan riil warga dan mengupayakan solusi (transport, sekolah) membuat relokasi diterima."},
{id:"TKP-1122", q:"Pembagian unit huntara dikeluhkan tidak merata: ada keluarga kecil dapat unit besar, keluarga besar dapat unit kecil. Kecemburuan muncul. Tindakan Anda?", opts:[{t:"Mengevaluasi ulang pembagian berdasarkan kriteria yang adil dan transparan (jumlah anggota keluarga, kebutuhan khusus), lalu mensosialisasikannya", s:5},{t:"Menjelaskan kriteria pembagian yang dipakai", s:4},{t:"Meminta warga menerima apa adanya karena unit terbatas", s:3},{t:"Menukar unit yang diprotes secara acak", s:2},{t:"Mengabaikan keluhan karena semua sudah kebagian", s:1}], ex:"Skor 5 terbaik: evaluasi berbasis kriteria adil yang transparan menyelesaikan kecemburuan secara sistemik."},
{id:"TKP-1123", q:"Pasca-bencana, banyak pelaku UMKM kehilangan modal dan peralatan usaha. Mereka meminta bantuan modal agar bisa bangkit. Program yang ada baru tahap perencanaan. Sikap Anda?", opts:[{t:"Mendata kebutuhan UMKM secara rinci, mengusulkan percepatan program bantuan modal, dan menghubungkan mereka dengan program pemberdayaan yang sudah ada", s:5},{t:"Mencatat usulan mereka untuk disampaikan ke atasan", s:4},{t:"Meminta mereka menunggu program resmi turun", s:3},{t:"Menyarankan mereka meminjam ke bank sendiri", s:2},{t:"Menolak karena di luar tugas Anda", s:1}], ex:"Skor 5 terbaik: pendataan konkret + advokasi percepatan + menghubungkan ke program eksisting — memulihkan ekonomi warga secara aktif."},
{id:"TKP-1124", q:"Beberapa ASN di unit Anda juga menjadi korban banjir: rumahnya terendam, namun mereka tetap diminta bertugas di posko. Semangat mereka menurun. Sebagai rekan, apa yang Anda lakukan?", opts:[{t:"Mengusulkan pengaturan shift yang manusiawi, membantu meringankan beban mereka, dan memberi dukungan moral agar mereka bisa memulihkan diri", s:5},{t:"Memberi semangat agar tetap profesional bertugas", s:4},{t:"Membiarkan mereka mengatur sendiri", s:3},{t:"Melaporkan mereka ke atasan karena kinerjanya menurun", s:2},{t:"Menganggap itu risiko pekerjaan dan bukan urusan Anda", s:1}], ex:"Skor 5 terbaik: ASN korban bencana butuh dukungan, bukan tekanan; pengaturan manusiawi menjaga kinerja dan kemanusiaan."},
{id:"TKP-1125", q:"Desa di pegunungan terisolir total pasca-gempa dan belum tersentuh layanan administrasi maupun bantuan. Warga mulai putus asa. Apa inisiatif Anda?", opts:[{t:"Mengusulkan dan melaksanakan layanan keliling (jemput bola) dengan tim gabungan membawa bantuan dan layanan administrasi dasar ke desa tersebut", s:5},{t:"Melaporkan kondisi desa itu ke atasan", s:4},{t:"Menunggu akses pulih sebelum mengirim bantuan", s:3},{t:"Menyuruh warga desa turun ke posko terdekat", s:2},{t:"Menganggap desa itu di luar wilayah tanggung jawab", s:1}], ex:"Skor 5 terbaik: layanan keliling proaktif menjangkau yang terisolir — negara hadir justru di titik tersulit."},
{id:"TKP-1126", q:"Warga membutuhkan surat keterangan bencana untuk klaim asuransi dan pengajuan keringanan kredit bank. Mereka bingung prosedurnya. Bagaimana Anda membantu?", opts:[{t:"Membuat alur layanan yang jelas, membantu melengkapi persyaratan, dan berkoordinasi dengan pihak bank/asuransi agar prosesnya lancar", s:5},{t:"Menerbitkan surat keterangan sesuai permohonan", s:4},{t:"Memberi tahu syarat-syaratnya saja", s:3},{t:"Menyuruh warga mengurus sendiri ke bank", s:2},{t:"Menolak karena bukan layanan rutin", s:1}], ex:"Skor 5 terbaik: pendampingan menyeluruh hingga koordinasi dengan pihak ketiga — memudahkan warga di masa sulit."},
{id:"TKP-1127", q:"Tim Anda ditugaskan mendata kerusakan rumah warga (rusak berat, sedang, ringan) sebagai dasar bantuan rehabilitasi. Warga berebut agar rumahnya dikategorikan rusak berat. Bagaimana Anda menjaga objektivitas?", opts:[{t:"Menerapkan kriteria teknis yang jelas dan terdokumentasi (foto, pengukuran), melibatkan tim verifikasi, dan menjelaskan kriteria ke warga", s:5},{t:"Menilai seadil mungkin berdasarkan pengamatan", s:4},{t:"Mengikuti penilaian ketua RT setempat", s:3},{t:"Mengategorikan semua sebagai rusak berat agar warga senang", s:2},{t:"Menilai asal-asalan agar cepat selesai", s:1}], ex:"Skor 5 terbaik: kriteria teknis terdokumentasi + verifikasi tim melindungi objektivitas dari tekanan dan memastikan bantuan tepat sasaran."},
{id:"TKP-1128", q:"Pasca-longsor, batas tanah antar-warga menjadi tidak jelas dan memicu sengketa. Kedua belah pihak meminta perangkat desa memutuskan. Sikap Anda?", opts:[{t:"Memfasilitasi mediasi dengan data (peta, saksi, dokumen lama), melibatkan BPN jika perlu, dan mencari kesepakatan yang adil", s:5},{t:"Menyarankan mereka menempuh jalur hukum", s:4},{t:"Memutuskan sepihak berdasarkan perkiraan", s:3},{t:"Memihak warga yang lebih berpengaruh", s:2},{t:"Menolak terlibat karena itu urusan pribadi", s:1}], ex:"Skor 5 terbaik: mediasi berbasis data dan melibatkan otoritas pertanahan menyelesaikan sengketa secara adil dan damai."},
{id:"TKP-1129", q:"Bencana merenggut kedua orang tua dari tiga anak kecil. Keluarga besar berebut hak asuh, sementara panti asuhan menawarkan menampung. Sebagai petugas sosial, apa yang Anda lakukan?", opts:[{t:"Mengutamakan kepentingan terbaik anak: memfasilitasi musyawarah keluarga, menilai kesiapan calon pengasuh, dan memastikan pendampingan psikososial", s:5},{t:"Menyerahkan ke keluarga terdekat yang bersedia", s:4},{t:"Menitipkan ke panti asuhan agar terjamin", s:3},{t:"Membiarkan keluarga menyelesaikan sendiri", s:2},{t:"Mengambil keputusan sepihak tanpa musyawarah", s:1}], ex:"Skor 5 terbaik: kepentingan terbaik anak di atas segalanya — fasilitasi musyawarah plus asesmen kesiapan pengasuh."},
{id:"TKP-1130", q:"Seorang lansia penderita demensia tersesat saat evakuasi dan ditemukan warga di desa lain dalam keadaan bingung. Tidak ada identitas padanya. Tindakan Anda?", opts:[{t:"Memberi perawatan sementara, mengumumkan penemuannya ke semua posko dan grup koordinasi, serta berkoordinasi dengan dinas sosial untuk penanganan lanjutan", s:5},{t:"Menitipkannya ke panti jompo terdekat", s:4},{t:"Mengumumkannya sekali di posko", s:3},{t:"Membiarkannya di tempat penemuan", s:2},{t:"Menganggap bukan tanggung jawab tim bencana", s:1}], ex:"Skor 5 terbaik: perawatan + pencarian keluarga intensif + koordinasi dinas sosial — perlindungan maksimal bagi lansia rentan."},
{id:"TKP-1131", q:"Anda mendapati oknum petugas memotong jatah bansos warga dengan dalih 'uang rokok' dan 'biaya administrasi'. Warga takut melapor. Apa yang Anda lakukan?", opts:[{t:"Mengumpulkan bukti dan melaporkan oknum tersebut melalui jalur resmi (inspektorat/whistleblowing system) serta mendampingi warga yang dirugikan", s:5},{t:"Menegur oknum tersebut agar berhenti", s:4},{t:"Melaporkan ke atasan langsung", s:3},{t:"Membiarkan karena tidak ingin bermasalah dengan rekan", s:2},{t:"Ikut menutup-nutupi karena sesama petugas", s:1}], ex:"Skor 5 terbaik: pungli bansos adalah kejahatan; laporan resmi plus pendampingan korban menegakkan integritas dan melindungi warga."},
{id:"TKP-1132", q:"Ketua RT terbukti menggelembungkan data penerima bansos dengan memasukkan nama-nama fiktif. Bantuan untuk nama fiktif itu diduga dinikmatinya. Tindakan Anda?", opts:[{t:"Melaporkan temuan dengan bukti ke jalur resmi dan mengusulkan verifikasi ulang data penerima di wilayah tersebut", s:5},{t:"Menegur ketua RT agar memperbaiki data", s:4},{t:"Mencoret nama fiktif secara diam-diam", s:3},{t:"Membiarkan karena takut konflik dengan tokoh masyarakat", s:2},{t:"Meminta bagian agar ikut diam", s:1}], ex:"Skor 5 terbaik: pemalsuan data bansos merugikan warga miskin yang berhak; laporan resmi plus verifikasi ulang adalah tindakan berintegritas."},
{id:"TKP-1133", q:"Perangkat desa menyalurkan bantuan bencana terlebih dahulu kepada kerabat dan orang dekatnya, sementara warga lain yang lebih membutuhkan belum kebagian. Anda mengetahuinya. Sikap Anda?", opts:[{t:"Menegur dan mengingatkan prinsip keadilan, serta melaporkan penyimpangan tersebut ke atasan/jalur resmi", s:5},{t:"Mengingatkan perangkat desa agar membagi adil", s:4},{t:"Mendiamkan karena itu wewenang desa", s:3},{t:"Ikut meminta jatah untuk keluarga Anda", s:2},{t:"Menganggap wajar karena sudah tradisi", s:1}], ex:"Skor 5 terbaik: nepotisme dalam penyaluran bantuan adalah ketidakadilan; diingatkan lalu dilaporkan bila berlanjut."},
{id:"TKP-1134", q:"Atasan Anda memerintahkan agar penyaluran bantuan diprioritaskan ke desa asalnya meskipun ada desa lain yang kerusakannya jauh lebih parah. Bagaimana Anda menyikapi?", opts:[{t:"Menolak perintah tersebut secara santun dengan menjelaskan data kerusakan, dan mengusulkan penyaluran berdasarkan tingkat kebutuhan", s:5},{t:"Menyampaikan data kerusakan agar atasan mempertimbangkan ulang", s:4},{t:"Melaksanakan perintah karena itu instruksi atasan", s:3},{t:"Melaksanakan sambil mengeluh ke rekan", s:2},{t:"Melaksanakan dan ikut menutupi", s:1}], ex:"Skor 5 terbaik: perintah yang melanggar prinsip keadilan wajib ditolak secara santun dengan argumen data — loyalitas pada aturan di atas loyalitas personal."},
{id:"TKP-1135", q:"Seorang supplier logistik bencana menawarkan 'fee' kepada Anda agar perusahaannya terus dipilih sebagai rekanan pengadaan, meski kualitas barangnya biasa saja. Tindakan Anda?", opts:[{t:"Menolak tegas tawaran tersebut dan melaporkannya, serta memastikan pemilihan rekanan berdasarkan kualitas dan harga yang wajar", s:5},{t:"Menolak tawaran tetapi tidak melaporkan", s:4},{t:"Mempertimbangkan karena barangnya masih bisa dipakai", s:3},{t:"Menerima fee dan tetap memilih supplier itu", s:2},{t:"Meminta fee lebih besar", s:1}], ex:"Skor 5 terbaik: tolak dan laporkan — gratifikasi dalam pengadaan bencana merugikan kualitas bantuan untuk korban."},
{id:"TKP-1136", q:"Donasi uang tunai dari masyarakat masuk ke rekening pribadi ketua panitia posko dengan alasan 'agar cepat'. Tidak ada pencatatan resmi. Anda curiga ada penyalahgunaan. Apa yang Anda lakukan?", opts:[{t:"Mendesak agar dana dipindahkan ke rekening resmi dengan pembukuan transparan, dan melaporkan kejanggalan ke atasan/pengawas", s:5},{t:"Menyarankan ketua panitia membuat laporan penggunaan dana", s:4},{t:"Mempercayai ketua panitia karena niatnya baik", s:3},{t:"Membiarkan karena bukan urusan Anda", s:2},{t:"Ikut menggunakan dana itu untuk keperluan posko tanpa catat", s:1}], ex:"Skor 5 terbaik: dana publik wajib dikelola transparan di rekening resmi; desakan pembukuan plus pelaporan mencegah penyelewengan."},
{id:"TKP-1137", q:"Laporan distribusi bantuan yang dibuat rekan Anda tidak sesuai fakta: jumlah yang disalurkan digelembungkan agar terlihat semua target tercapai. Atasan meminta Anda ikut menandatangani. Sikap Anda?", opts:[{t:"Menolak menandatangani laporan yang tidak benar dan menyampaikan data sebenarnya melalui jalur yang tepat", s:5},{t:"Menandatangani dengan catatan keberatan", s:4},{t:"Menandatangani karena semua rekan melakukannya", s:3},{t:"Menandatangani agar tidak dimusuhi rekan", s:2},{t:"Ikut membantu menggelembungkan data", s:1}], ex:"Skor 5 terbaik: menolak memalsukan dokumen negara; integritas tidak bisa ditukar dengan solidaritas semu."},
{id:"TKP-1138", q:"Foto dokumentasi pembagian bantuan bencana dipakai oleh tim sukses calon kepala daerah untuk materi kampanye tanpa izin. Warga yang difoto keberatan. Apa yang Anda lakukan?", opts:[{t:"Menegur dan meminta materi tersebut ditarik, serta memastikan dokumentasi bantuan tidak dipolitisasi dan martabat warga dilindungi", s:5},{t:"Mengingatkan tim sukses agar meminta izin dulu", s:4},{t:"Membiarkan karena membantu popularitas program", s:3},{t:"Ikut menyebarkan foto tersebut", s:2},{t:"Menganggap itu hal biasa dalam politik", s:1}], ex:"Skor 5 terbaik: bantuan kemanusiaan tidak boleh jadi alat kampanye; melindungi warga dari eksploitasi politik adalah tugas ASN netral."},
{id:"TKP-1139", q:"Barang bantuan dari rekanan (selimut, terpal) ternyata berkualitas sangat buruk dan tidak layak pakai, tetapi pengadaannya sudah dibayar lunas. Apa tindakan Anda?", opts:[{t:"Melaporkan ketidaksesuaian spesifikasi ke atasan dan mengusulkan klaim/garansi ke rekanan, serta memastikan pengadaan berikutnya diawasi ketat", s:5},{t:"Menerima seadanya karena keadaan darurat", s:4},{t:"Membagikan yang masih bisa dipakai", s:3},{t:"Menyimpan di gudang tanpa laporan", s:2},{t:"Membuangnya diam-diam", s:1}], ex:"Skor 5 terbaik: uang negara harus dipertanggungjawabkan; klaim ke rekanan melindungi hak korban atas bantuan layak."},
{id:"TKP-1140", q:"Kendaraan dinas yang seharusnya untuk distribusi bantuan dipakai oknum untuk keperluan pribadi mengangkut barang dagangannya saat masa tanggap darurat. Anda melihatnya. Tindakan Anda?", opts:[{t:"Melaporkan penyalahgunaan aset negara tersebut ke atasan/jalur resmi dengan bukti", s:5},{t:"Menegur oknum tersebut secara pribadi", s:4},{t:"Mendiamkan karena tidak ingin bermasalah", s:3},{t:"Meminjam juga untuk keperluan pribadi", s:2},{t:"Menganggap wajar karena situasi darurat", s:1}], ex:"Skor 5 terbaik: aset negara untuk penanganan bencana disalahgunakan — wajib dilaporkan resmi, bukan didiamkan."},
{id:"TKP-1141", q:"Seorang ASN meninggalkan posko pengungsian saat jam tugas untuk pulang tidur, padahal ia dijadwalkan piket malam. Akibatnya distribusi obat malam itu terganggu. Anda rekan satu timnya. Sikap Anda?", opts:[{t:"Menegur dan melaporkannya ke koordinator posko karena telah menelantarkan tugas yang menyangkut kebutuhan pengungsi", s:5},{t:"Menegurnya agar tidak mengulangi", s:4},{t:"Menggantikan tugasnya malam itu tanpa komentar", s:3},{t:"Membiarkan karena ia mungkin kelelahan", s:2},{t:"Ikut pulang karena tidak ada yang mengawasi", s:1}], ex:"Skor 5 terbaik: menelantarkan tugas di masa darurat berdampak pada nyawa; ditegur dan dilaporkan agar ada efek jera."},
{id:"TKP-1142", q:"Petugas piket malam posko tertidur saat terjadi kebocoran gas di dapur umum. Beruntung tidak terjadi kebakaran. Bagaimana Anda menyikapi kelalaian ini?", opts:[{t:"Melaporkan kejadian ke koordinator, mengusulkan evaluasi sistem piket (jadwal, pengawasan), dan memastikan ada perbaikan", s:5},{t:"Menegur petugas tersebut dengan keras", s:4},{t:"Menganggapnya musibah yang tidak perlu dibesar-besarkan", s:3},{t:"Menyembunyikan kejadian agar posko tidak dinilai buruk", s:2},{t:"Membiarkan karena semua petugas kelelahan", s:1}], ex:"Skor 5 terbaik: kelalaian yang membahayakan keselamatan dievaluasi sistemik (bukan sekadar dimarahi) agar tidak terulang."},
{id:"TKP-1143", q:"Rekan Anda menyebarkan informasi jumlah korban bencana yang belum terverifikasi ke grup media sosial dan menimbulkan kepanikan. Data resmi belum keluar. Apa yang Anda lakukan?", opts:[{t:"Meminta rekan menghapus informasi tersebut, menjelaskan pentingnya menunggu data resmi, dan membantu menyebarkan klarifikasi", s:5},{t:"Mengingatkan rekan agar tidak menyebar info belum pasti", s:4},{t:"Membiarkan karena niatnya memberi informasi", s:3},{t:"Ikut menyebarkan agar warga waspada", s:2},{t:"Menambah-nambahi informasi agar terlihat update", s:1}], ex:"Skor 5 terbaik: informasi korban yang salah menimbulkan kepanikan dan melukai keluarga; koreksi aktif plus klarifikasi adalah tanggung jawab."},
{id:"TKP-1144", q:"Data pribadi pengungsi (nama, NIK, kondisi kesehatan) bocor dan tersebar di media sosial karena kelalaian petugas input. Beberapa pengungsi protes. Tindakan Anda?", opts:[{t:"Segera berkoordinasi mengamankan data, meminta penghapusan sebaran, meminta maaf kepada pengungsi, dan memperbaiki SOP pengamanan data", s:5},{t:"Meminta maaf kepada pengungsi yang protes", s:4},{t:"Menyalahkan petugas input yang lalai", s:3},{t:"Menganggap data pengungsi bukan data sensitif", s:2},{t:"Menutup-nutupi kebocoran tersebut", s:1}], ex:"Skor 5 terbaik: kebocoran data ditangani serius — pengamanan, penghapusan sebaran, permintaan maaf, dan perbaikan SOP."},
{id:"TKP-1145", q:"Seorang warga menawarkan uang kepada Anda agar namanya dimasukkan ke daftar penerima bantuan padahal ia tidak terdampak bencana. Ia memaksa dengan dalih 'semua juga begitu'. Sikap Anda?", opts:[{t:"Menolak dengan tegas, menjelaskan bahwa bantuan hanya untuk korban, dan mencatat upaya suap tersebut untuk dilaporkan bila perlu", s:5},{t:"Menolak tawarannya dengan halus", s:4},{t:"Menyuruhnya mendaftar lewat RT seperti warga lain", s:3},{t:"Menerima uangnya tetapi tidak memasukkan namanya", s:2},{t:"Menerima dan memasukkan namanya", s:1}], ex:"Skor 5 terbaik: penolakan tegas plus pencatatan — suap dalam penyaluran bantuan adalah korupsi yang merampas hak korban."},
{id:"TKP-1146", q:"Menjelang pemilu, seorang politikus menekan Anda agar penyaluran bansos diarahkan ke kantong-kantong basis suaranya dengan imbalan kemudahan karier. Bagaimana Anda menyikapi?", opts:[{t:"Menolak tegas segala bentuk intervensi politik dan tetap menyalurkan bansos berdasarkan data kebutuhan yang objektif", s:5},{t:"Menolak dengan halus tanpa melaporkan", s:4},{t:"Menuruti sebagian agar tidak dimusuhi", s:3},{t:"Menuruti karena menguntungkan karier", s:2},{t:"Aktif membantu kampanyenya lewat bansos", s:1}], ex:"Skor 5 terbaik: netralitas ASN adalah harga mati; bansos untuk rakyat miskin, bukan alat politik — tolak dan tetap objektif."},
{id:"TKP-1147", q:"Atasan meminta Anda membuat laporan 'semua beres' tentang penanganan bencana untuk disampaikan ke pimpinan daerah, padahal distribusi di tiga desa belum tuntas. Apa yang Anda lakukan?", opts:[{t:"Menyampaikan laporan apa adanya sesuai fakta lapangan dan mengusulkan langkah percepatan untuk desa yang belum tuntas", s:5},{t:"Membuat laporan sesuai fakta tanpa usulan tindak lanjut", s:4},{t:"Membuat laporan 'beres' sesuai perintah atasan", s:3},{t:"Membuat laporan beres agar atasan senang", s:2},{t:"Membuat laporan beres dan memanipulasi data pendukung", s:1}], ex:"Skor 5 terbaik: laporan fiktif mengorbankan warga tiga desa; kejujuran plus solusi adalah integritas yang bertanggung jawab."},
{id:"TKP-1148", q:"Seorang teman pengusaha meminta data penerima bansos kepada Anda untuk 'penawaran produk'. Ia menjanjikan imbalan. Bagaimana Anda menyikapi?", opts:[{t:"Menolak karena data penerima adalah data pribadi yang dilindungi dan tidak boleh diperjualbelikan", s:5},{t:"Menolak dengan alasan sibuk", s:4},{t:"Memberikan data yang sudah disamarkan", s:3},{t:"Memberikan sebagian data", s:2},{t:"Memberikan data lengkap demi imbalan", s:1}], ex:"Skor 5 terbaik: data warga miskin bukan komoditas; penolakan tegas melindungi privasi dan martabat penerima bansos."},
{id:"TKP-1149", q:"Anda melihat rekan mengambil jatah sembako petugas posko jauh melebihi porsi yang ditentukan, dengan alasan untuk keluarganya di rumah. Sikap Anda?", opts:[{t:"Menegur dan mengingatkannya bahwa jatah petugas sudah ditentukan dan kelebihannya adalah hak pengungsi", s:5},{t:"Mengingatkannya secara pribadi", s:4},{t:"Membiarkan karena kasihan pada keluarganya", s:3},{t:"Ikut mengambil lebih juga", s:2},{t:"Menganggap hal kecil tidak perlu diributkan", s:1}], ex:"Skor 5 terbaik: setiap paket sembako yang diambil berlebih adalah hak pengungsi yang hilang; diingatkan dengan tegas."},
{id:"TKP-1150", q:"Uang santunan duka untuk keluarga korban bencana dipotong oleh oknum dengan dalih biaya administrasi, padahal seharusnya diterima utuh. Keluarga korban mengadu kepada Anda. Tindakan Anda?", opts:[{t:"Menindaklanjuti aduan dengan serius, memastikan keluarga menerima santunan utuh, dan melaporkan oknum ke jalur resmi", s:5},{t:"Menyarankan keluarga melapor ke atasan", s:4},{t:"Menegur oknum tersebut", s:3},{t:"Menganggap potongan kecil hal biasa", s:2},{t:"Mengabaikan aduan tersebut", s:1}], ex:"Skor 5 terbaik: memotong santunan duka adalah perbuatan tercela; pastikan hak keluarga terpenuhi dan pelaku diproses."},
{id:"TKP-1151", q:"Pengadaan tenda darurat oleh unit Anda terindikasi mark-up: harga jauh di atas pasar dan kualitas rendah. Anda anggota tim pengadaan. Apa yang Anda lakukan?", opts:[{t:"Menolak menyetujui pengadaan bermasalah itu dan melaporkan indikasi mark-up melalui jalur resmi", s:5},{t:"Meminta penjelasan dari ketua tim pengadaan", s:4},{t:"Menyetujui karena kebutuhan mendesak", s:3},{t:"Menyetujui agar tidak menghambat penyaluran", s:2},{t:"Ikut menikmati selisih harganya", s:1}], ex:"Skor 5 terbaik: kedaruratan bukan alasan mark-up; penolakan plus pelaporan melindungi uang negara dan kualitas bantuan."},
{id:"TKP-1152", q:"Rekan Anda membuat SPJ fiktif untuk kegiatan tanggap darurat yang tidak pernah dilaksanakan dan meminta Anda ikut tanda tangan sebagai saksi. Sikap Anda?", opts:[{t:"Menolak terlibat dan melaporkan pembuatan SPJ fiktif tersebut ke inspektorat", s:5},{t:"Menolak menandatangani tetapi tidak melaporkan", s:4},{t:"Menandatangani karena nominalnya kecil", s:3},{t:"Menandatangani demi solidaritas tim", s:2},{t:"Ikut membuat SPJ fiktif lainnya", s:1}], ex:"Skor 5 terbaik: SPJ fiktif adalah korupsi; penolakan plus pelaporan memutus mata rantai penyimpangan."},
{id:"TKP-1153", q:"Seorang relawan gadungan meminta bayaran kepada pengungsi dengan dalih 'jasa evakuasi'. Pengungsi yang tidak paham hampir membayar. Anda mengetahuinya. Tindakan Anda?", opts:[{t:"Segera menghentikan aksinya, mengamankan pelaku, melaporkannya ke aparat, dan mengedukasi pengungsi agar tidak tertipu", s:5},{t:"Mengusir relawan gadungan dari posko", s:4},{t:"Memperingatkan pengungsi agar berhati-hati", s:3},{t:"Membiarkan karena bukan wewenang Anda", s:2},{t:"Menganggap itu urusan antar mereka", s:1}], ex:"Skor 5 terbaik: melindungi pengungsi dari penipuan — hentikan, amankan, laporkan, dan edukasi agar tidak ada korban berikutnya."},
{id:"TKP-1154", q:"Oknum petugas menjual paket bantuan yang seharusnya gratis kepada warga dengan harga murah. Warga yang tidak tahu menganggap itu memang berbayar. Apa yang Anda lakukan?", opts:[{t:"Menghentikan praktik tersebut, memastikan bantuan disalurkan gratis sesuai ketentuan, dan melaporkan oknum ke jalur resmi", s:5},{t:"Menegur oknum tersebut", s:4},{t:"Memberi tahu warga bahwa bantuan seharusnya gratis", s:3},{t:"Membiarkan karena harganya murah", s:2},{t:"Ikut menjual karena menguntungkan", s:1}], ex:"Skor 5 terbaik: memperjualbelikan bantuan gratis adalah pengkhianatan terhadap korban; hentikan, pulihkan hak warga, laporkan pelaku."},
{id:"TKP-1155", q:"Untuk mendapatkan surat keterangan terdampak bencana, warga diminta membayar 'uang cepat' oleh oknum loket. Antrean reguler sangat lambat. Sikap Anda sebagai petugas yang mengetahui?", opts:[{t:"Melaporkan praktik pungli tersebut dan mengusulkan perbaikan sistem antrean agar warga tidak terjebak memilih membayar", s:5},{t:"Menegur oknum loket", s:4},{t:"Melayani warga tanpa pungli di loket Anda", s:3},{t:"Membiarkan karena antrean memang lambat", s:2},{t:"Ikut memungut karena semua melakukannya", s:1}], ex:"Skor 5 terbaik: pungli diberantas lewat pelaporan plus perbaikan sistem — mengatasi penyebab, bukan sekadar gejala."},
{id:"TKP-1156", q:"Petugas kesehatan di posko menolak melayani pengungsi yang sakit kecuali diberi 'uang terima kasih' terlebih dahulu. Seorang ibu menangis karena tidak punya uang. Tindakan Anda?", opts:[{t:"Menegur keras praktik tersebut, memastikan ibu itu segera dilayani, dan melaporkan oknum ke dinas kesehatan", s:5},{t:"Membayarkan 'uang terima kasih' agar ibu itu dilayani", s:4},{t:"Meminta petugas melayani dengan alasan kemanusiaan", s:3},{t:"Menyarankan ibu mencari pengobatan di tempat lain", s:2},{t:"Membiarkan karena itu urusan tenaga kesehatan", s:1}], ex:"Skor 5 terbaik: pelayanan kesehatan darurat tidak boleh dikomersialkan; pastikan korban terlayani dan pelaku diproses — bukan menormalkan pungli dengan membayarnya."},
{id:"TKP-1157", q:"Daftar hadir petugas posko dipalsukan: ada nama yang tidak pernah datang tetapi tercatat hadir penuh untuk klaim uang lembur. Anda diminta ikut menandatangani. Sikap Anda?", opts:[{t:"Menolak menandatangani dan melaporkan pemalsuan tersebut", s:5},{t:"Menolak tetapi tidak melaporkan", s:4},{t:"Menandatangani karena hanya formalitas", s:3},{t:"Menandatangani agar dapat bagian uang lembur", s:2},{t:"Ikut memasukkan nama fiktif", s:1}], ex:"Skor 5 terbaik: pemalsuan daftar hadir adalah fraud; penolakan plus pelaporan menjaga integritas pengelolaan anggaran bencana."},
{id:"TKP-1158", q:"Bantuan tahap kedua untuk korban banjir tak kunjung turun sudah dua bulan. Warga marah dan menuduh petugas posko menggelapkan. Bagaimana Anda menangani?", opts:[{t:"Menjelaskan dengan transparan status pengajuan bantuan, menunjukkan bukti prosesnya, dan aktif berkoordinasi mempercepat penyaluran", s:5},{t:"Menjelaskan bahwa keterlambatan dari pusat", s:4},{t:"Meminta warga bersabar menunggu", s:3},{t:"Menyalahkan pemerintah pusat di depan warga", s:2},{t:"Menghindar dari warga yang menuntut", s:1}], ex:"Skor 5 terbaik: transparansi status plus bukti proses meredam tuduhan; koordinasi aktif mempercepat — bukan sekadar meminta sabar."},
{id:"TKP-1159", q:"Terjadi kesalahan input data: nama penerima bantuan tertukar sehingga warga yang berhak tidak menerima dan yang tidak berhak menerima. Warga yang dirugikan protes. Tindakan Anda?", opts:[{t:"Mengakui kesalahan, segera memperbaiki data, menarik kembali bantuan yang salah sasaran bila memungkinkan, dan menyalurkan ke yang berhak", s:5},{t:"Memperbaiki data untuk penyaluran berikutnya", s:4},{t:"Menyalahkan petugas input", s:3},{t:"Menganggap kesalahan kecil yang tidak perlu diributkan", s:2},{t:"Menutup-nutupi kesalahan tersebut", s:1}], ex:"Skor 5 terbaik: mengakui kesalahan, memperbaiki, dan memulihkan hak yang dirugikan — akuntabilitas penuh tanpa mencari kambing hitam."},
{id:"TKP-1160", q:"Keluhan warga tentang pelayanan posko viral di media sosial dan dinilai mempermalukan instansi. Atasan marah dan meminta Anda mencari siapa yang menyebar. Sikap Anda?", opts:[{t:"Menjadikan keluhan viral sebagai bahan evaluasi, memperbaiki kekurangan pelayanan, dan menyampaikan klarifikasi resmi yang santun", s:5},{t:"Menyampaikan klarifikasi resmi", s:4},{t:"Mencari penyebar keluhan untuk ditegur", s:3},{t:"Menyerang balik warga di media sosial", s:2},{t:"Mengabaikan karena hanya viral sesaat", s:1}], ex:"Skor 5 terbaik: kritik publik adalah cermin untuk berbenah; evaluasi dan perbaikan lebih berharga daripada mencari kambing hitam."},
{id:"TKP-1161", q:"Anda sudah bertugas tiga hari tiga malam hampir tanpa istirahat di posko bencana. Konsentrasi mulai menurun dan Anda khawatir membuat kesalahan fatal dalam pendataan bantuan. Apa yang Anda lakukan?", opts:[{t:"Melaporkan kondisi ke koordinator, meminta pergantian shift sementara untuk istirahat, dan kembali bertugas setelah pulih", s:5},{t:"Meminta rekan membantu memverifikasi pekerjaan Anda", s:4},{t:"Memaksakan diri terus bertugas", s:3},{t:"Mengerjakan seadanya sambil menunggu shift berakhir", s:2},{t:"Meninggalkan posko tanpa pemberitahuan", s:1}], ex:"Skor 5 terbaik: mengakui keterbatasan dan meminta pergantian adalah profesionalisme — kelelahan yang dipaksakan justru membahayakan pelayanan."},
{id:"TKP-1162", q:"Keluarga Anda sendiri menjadi korban banjir dan membutuhkan bantuan, sementara Anda ditugaskan melayani pengungsi lain di posko. Ada godaan mendahulukan keluarga. Sikap Anda?", opts:[{t:"Tetap melayani sesuai antrean dan prioritas yang berlaku, mempercayakan keluarga pada mekanisme yang sama seperti warga lain", s:5},{t:"Meminta rekan membantu keluarga Anda lewat jalur resmi", s:4},{t:"Diam-diam mendahulukan keluarga", s:3},{t:"Meninggalkan tugas untuk mengurus keluarga", s:2},{t:"Mengambil jatah bantuan lebih untuk keluarga", s:1}], ex:"Skor 5 terbaik: integritas berarti tidak memanfaatkan jabatan untuk kepentingan keluarga; semua korban setara di hadapan pelayanan."},
{id:"TKP-1163", q:"Dalam keadaan darurat Anda ditugaskan di luar tupoksi: mengemudikan perahu karet untuk evakuasi padahal Anda staf administrasi. Anda belum pernah melakukannya. Sikap Anda?", opts:[{t:"Menerima tugas dengan meminta briefing keselamatan singkat dari tim SAR dan melaksanakannya dengan hati-hati", s:5},{t:"Menerima tugas dan belajar sambil jalan", s:4},{t:"Menolak karena bukan tupoksi", s:3},{t:"Menerima tetapi asal-asalan", s:2},{t:"Menghilang agar tidak ditugaskan", s:1}], ex:"Skor 5 terbaik: kedaruratan menuntut fleksibilitas; menerima dengan bekal briefing keselamatan menyeimbangkan keberanian dan kehati-hatian."},
{id:"TKP-1164", q:"Atasan memerintahkan Anda memprioritaskan dokumentasi seremonial (foto-foto) daripada penyaluran bantuan yang mendesak, demi citra pimpinan. Bagaimana Anda menyikapi?", opts:[{t:"Menolak secara santun dan menjelaskan bahwa penyaluran bantuan yang menyelamatkan nyawa harus didahulukan", s:5},{t:"Menyarankan dokumentasi dilakukan tanpa mengganggu penyaluran", s:4},{t:"Melaksanakan perintah atasan", s:3},{t:"Melaksanakan sambil menunda penyaluran", s:2},{t:"Melaksanakan dengan antusias demi citra pimpinan", s:1}], ex:"Skor 5 terbaik: nyawa warga di atas pencitraan; penolakan santun berbasis prioritas kemanusiaan adalah keberanian berintegritas."},
{id:"TKP-1165", q:"Anda menyaksikan rekan satu tim mengambil sebagian logistik bantuan untuk dijual. Ia mengancam akan menyebarkan fitnah tentang Anda jika melapor. Apa yang Anda lakukan?", opts:[{t:"Tetap melaporkan melalui whistleblowing system yang melindungi identitas pelapor, karena kebenaran tidak boleh dibungkam ancaman", s:5},{t:"Melaporkan langsung ke atasan meski berisiko", s:4},{t:"Mengumpulkan bukti dulu sambil menunda laporan", s:3},{t:"Diam karena takut ancaman", s:2},{t:"Ikut serta agar aman", s:1}], ex:"Skor 5 terbaik: ancaman tidak boleh membungkam kebenaran; jalur whistleblowing yang aman adalah perlindungan yang tepat."},
{id:"TKP-1166", q:"Relawan di posko mengenakan kaus bergambar calon kepala daerah dan membagikan bantuan sambil mengajak memilih. Warga resah. Sebagai koordinator, tindakan Anda?", opts:[{t:"Menegur dan melarang atribut kampanye di area posko, menegaskan posko netral dan bantuan tidak boleh dipolitisasi", s:5},{t:"Meminta relawan melepas kaus saat bertugas", s:4},{t:"Membiarkan karena ia relawan bukan ASN", s:3},{t:"Mempersilakan asal bantuan tetap jalan", s:2},{t:"Ikut mendukung calon tersebut", s:1}], ex:"Skor 5 terbaik: netralitas ruang kemanusiaan wajib dijaga; bantuan untuk korban tidak boleh jadi kendaraan politik siapa pun."},
{id:"TKP-1167", q:"Seorang pengungsi penderita HIV meminta datanya dirahasiakan, tetapi rekan Anda ingin mengumumkan statusnya dengan dalih 'kewaspadaan bersama'. Sikap Anda?", opts:[{t:"Melarang keras penyebaran data kesehatan tersebut dan mengingatkan kewajiban kerahasiaan serta perlindungan dari stigma", s:5},{t:"Menasihati rekan agar tidak menyebarkan", s:4},{t:"Membiarkan karena alasan kewaspadaan", s:3},{t:"Ikut menyebarkan agar semua waspada", s:2},{t:"Mengumumkan sendiri ke pengungsi lain", s:1}], ex:"Skor 5 terbaik: data kesehatan dilindungi undang-undang; melarang penyebaran melindungi martabat dan hak pengungsi."},
{id:"TKP-1168", q:"Setiap distribusi bantuan di posko Anda catat rinci: jenis, jumlah, penerima, dan sisa. Rekan menganggap Anda berlebihan dan buang waktu. Bagaimana Anda menyikapi?", opts:[{t:"Tetap mencatat dengan tertib karena akuntabilitas adalah kewajiban, dan menjelaskan manfaatnya saat audit/evaluasi", s:5},{t:"Tetap mencatat meski dianggap berlebihan", s:4},{t:"Mencatat seadanya agar tidak dicemooh", s:3},{t:"Berhenti mencatat mengikuti rekan", s:2},{t:"Ikut mencemooh petugas yang tertib administrasi", s:1}], ex:"Skor 5 terbaik: pencatatan rinci adalah akuntabilitas; keteguhan pada prinsip meski tidak populer adalah integritas."},
{id:"TKP-1169", q:"Evaluasi pasca-bencana menemukan banyak kekurangan penanganan di unit Anda. Atasan ingin laporan evaluasi dibuat 'bagus' agar tidak dimarahi pimpinan. Sikap Anda?", opts:[{t:"Menyusun evaluasi jujur berbasis fakta beserta rekomendasi perbaikan, karena evaluasi yang jujur menyelamatkan penanganan bencana berikutnya", s:5},{t:"Menyusun evaluasi jujur tanpa rekomendasi", s:4},{t:"Membuat evaluasi 'bagus' sesuai keinginan atasan", s:3},{t:"Membuat evaluasi bagus agar unit dinilai baik", s:2},{t:"Menolak membuat evaluasi sama sekali", s:1}], ex:"Skor 5 terbaik: evaluasi jujur adalah pembelajaran; menutup-nutupi kekurangan berarti mengulang kesalahan saat bencana berikutnya."},
{id:"TKP-1170", q:"Anda ditawari menjadi koordinator distribusi dengan 'fasilitas' berupa potongan dari setiap paket bantuan yang disalurkan. Tawaran datang dari pihak berpengaruh. Tindakan Anda?", opts:[{t:"Menolak tegas dan melaporkan tawaran tersebut, serta memastikan distribusi berjalan bersih", s:5},{t:"Menolak tawaran tetapi tidak melaporkan", s:4},{t:"Mempertimbangkan karena kebutuhannya mendesak", s:3},{t:"Menerima dengan hati-hati", s:2},{t:"Menerima dan mengatur skemanya", s:1}], ex:"Skor 5 terbaik: menolak dan melaporkan — tidak ada kompromi dengan korupsi bantuan bencana, dari siapa pun tawarannya."},
{id:"TKP-1171", q:"Anda ditugaskan dalam tim gabungan penanggulangan banjir bersama BPBD, TNI/Polri, dan relawan. Masing-masing pihak punya cara kerja sendiri dan koordinasi tersendat. Apa yang Anda lakukan?", opts:[{t:"Mengusulkan rapat koordinasi singkat untuk menyepakati pembagian tugas, jalur komando, dan mekanisme komunikasi yang jelas", s:5},{t:"Mengikuti arahan pihak yang paling dominan", s:4},{t:"Bekerja sendiri sesuai tugas instansi Anda", s:3},{t:"Menyalahkan pihak lain yang tidak kooperatif", s:2},{t:"Menarik diri dari tim gabungan", s:1}], ex:"Skor 5 terbaik: inisiatif menyatukan cara kerja lewat kesepakatan bersama — kolaborasi dimulai dari komunikasi yang disepakati."},
{id:"TKP-1172", q:"Di posko terjadi ego sektoral: dinas kesehatan hanya urus tenda medis, dinas sosial hanya urus logistik, dan korban yang butuh keduanya terlantar di antaranya. Bagaimana Anda menjembatani?", opts:[{t:"Mengusulkan mekanisme rujukan antar-tenda yang jelas dan petugas penghubung, agar korban terlayani menyeluruh tanpa sekat instansi", s:5},{t:"Meminta kedua dinas berkoordinasi lebih baik", s:4},{t:"Mengantar sendiri korban yang terlantar", s:3},{t:"Menyalahkan kedua dinas", s:2},{t:"Membiarkan karena itu masalah mereka", s:1}], ex:"Skor 5 terbaik: membangun jembatan sistemik (rujukan + penghubung) mengatasi ego sektoral, bukan sekadar mengimbau."},
{id:"TKP-1173", q:"Posko harus siaga 24 jam tetapi jumlah petugas terbatas. Pembagian shift piket selalu menimbulkan protes karena dianggap tidak adil. Solusi Anda?", opts:[{t:"Menyusun jadwal shift transparan yang adil (rotasi malam, beban seimbang), disepakati bersama, dan ditegakkan konsisten", s:5},{t:"Membagi shift berdasarkan keputusan koordinator", s:4},{t:"Membiarkan petugas mengatur sendiri", s:3},{t:"Memberi shift ringan ke yang dekat dengan koordinator", s:2},{t:"Tidak membuat jadwal, siapa sempat dia jaga", s:1}], ex:"Skor 5 terbaik: jadwal adil yang transparan dan disepakati menghilangkan protes dan menjamin kesiagaan 24 jam."},
{id:"TKP-1174", q:"Ratusan relawan berdatangan ke lokasi bencana tanpa koordinasi: ada yang menumpuk di satu titik, titik lain kosong. Kekacauan terjadi. Apa langkah Anda?", opts:[{t:"Mendirikan pusat registrasi relawan, memetakan kebutuhan tiap titik, dan menempatkan relawan sesuai keterampilan dan kebutuhan", s:5},{t:"Mengarahkan relawan ke titik yang kosong", s:4},{t:"Membiarkan relawan bekerja sesukanya", s:3},{t:"Melarang relawan baru datang", s:2},{t:"Mengusir relawan yang tidak terdaftar", s:1}], ex:"Skor 5 terbaik: mengorganisir (registrasi + pemetaan + penempatan) mengubah kerumunan jadi kekuatan terkoordinasi."},
{id:"TKP-1175", q:"Sebuah LSM internasional ingin membantu dengan standar operasional yang berbeda dari SOP nasional dan enggan berkoordinasi. Bantuannya besar dan dibutuhkan. Sikap Anda?", opts:[{t:"Menyambut bantuannya sambil menegosiasikan penyesuaian dengan SOP nasional dan menempatkan petugas penghubung", s:5},{t:"Menerima bantuan dengan SOP mereka", s:4},{t:"Menolak bantuan karena beda SOP", s:3},{t:"Membiarkan mereka bekerja sendiri", s:2},{t:"Melaporkan mereka sebagai penghambat", s:1}], ex:"Skor 5 terbaik: negosiasi win-win — bantuan besar tersalurkan dalam koridor SOP nasional lewat petugas penghubung."},
{id:"TKP-1176", q:"Desa terisolir hanya bisa dihubungi lewat radio komunikasi yang Anda tidak kuasai. Informasi kebutuhan mendesak mereka belum sampai. Apa yang Anda lakukan?", opts:[{t:"Segera belajar dasar pengoperasian radio dari tim yang bisa, atau meminta operator mendampingi, agar komunikasi tersambung", s:5},{t:"Meminta tim lain menangani komunikasi itu", s:4},{t:"Menunggu ada operator yang senggang", s:3},{t:"Mengabaikan karena tidak bisa mengoperasikan", s:2},{t:"Berpura-pura sudah menghubungi", s:1}], ex:"Skor 5 terbaik: keterbatasan keterampilan diatasi dengan belajar cepat atau meminta pendampingan — komunikasi dengan yang terisolir tidak boleh putus."},
{id:"TKP-1177", q:"Rapat koordinasi darurat yang Anda pimpin selalu molor dan tidak menghasilkan keputusan karena semua pihak bicara tanpa arah. Bagaimana Anda memperbaikinya?", opts:[{t:"Menerapkan disiplin rapat: agenda jelas, batas waktu bicara, fokus pada keputusan dan pembagian tugas, serta notulensi tindak lanjut", s:5},{t:"Membatasi waktu rapat maksimal 30 menit", s:4},{t:"Membiarkan semua bicara sampai puas", s:3},{t:"Mengambil keputusan sepihak tanpa rapat", s:2},{t:"Tidak mengadakan rapat lagi", s:1}], ex:"Skor 5 terbaik: rapat darurat harus menghasilkan keputusan; disiplin agenda dan tindak lanjut membuatnya efektif."},
{id:"TKP-1178", q:"Serah terima shift di posko berjalan buruk: informasi penting (stok menipis, kasus mendesak) tidak tersampaikan sehingga shift berikutnya kebingungan. Solusi Anda?", opts:[{t:"Membuat format serah terima baku (logbook + briefing singkat) yang wajib diisi dan dijelaskan setiap pergantian shift", s:5},{t:"Mengingatkan petugas agar saling memberi tahu", s:4},{t:"Membiarkan karena masing-masing sudah tahu tugasnya", s:3},{t:"Menyalahkan shift sebelumnya yang tidak memberi tahu", s:2},{t:"Menghapus sistem shift", s:1}], ex:"Skor 5 terbaik: sistem serah terima baku menjamin kontinuitas informasi — tidak bergantung pada ingatan personal."},
{id:"TKP-1179", q:"Tim medis dan tim logistik di posko berselisih: tim medis menuduh logistik lambat mengirim obat, logistik menuduh medis tidak jelas permintaannya. Pelayanan terganggu. Tindakan Anda?", opts:[{t:"Memfasilitasi pertemuan keduanya, menyepakati format permintaan obat yang jelas dan jadwal pengiriman rutin, serta mekanisme konfirmasi", s:5},{t:"Meminta keduanya menahan diri dan fokus bekerja", s:4},{t:"Memihak tim medis karena menyangkut nyawa", s:3},{t:"Memihak tim logistik karena keterbatasan stok", s:2},{t:"Membiarkan mereka menyelesaikan sendiri", s:1}], ex:"Skor 5 terbaik: mediasi yang menghasilkan kesepakatan operasional konkret menyelesaikan konflik sekaligus memperbaiki sistem."},
{id:"TKP-1180", q:"Data korban antar-posko berbeda-beda sehingga bantuan menumpuk di satu posko dan kurang di posko lain. Masing-masing posko enggan berbagi data. Apa yang Anda lakukan?", opts:[{t:"Mengusulkan sistem data terpadu dengan format standar dan petugas penghubung antar-posko, serta update berkala", s:5},{t:"Meminta tiap posko mengirim datanya ke pusat", s:4},{t:"Menggunakan data perkiraan sendiri", s:3},{t:"Membiarkan tiap posko dengan datanya", s:2},{t:"Menyalahkan posko yang tidak mau berbagi", s:1}], ex:"Skor 5 terbaik: data terpadu berformat standar menghilangkan silo informasi dan pemerataan bantuan tercapai."},
{id:"TKP-1181", q:"Warga terdampak banjir bergotong royong membersihkan lumpur di kampungnya, tetapi semangat mereka kendor di hari ketiga karena lelah dan bantuan belum datang. Sebagai petugas, apa yang Anda lakukan?", opts:[{t:"Turun langsung ikut bergotong royong, memberi semangat, dan memastikan kebutuhan dasar mereka (makan, minum, alat) terpenuhi", s:5},{t:"Memberi semangat dan motivasi agar tidak menyerah", s:4},{t:"Menjanjikan bantuan segera datang", s:3},{t:"Menyuruh mereka bersabar", s:2},{t:"Meninggalkan mereka karena itu urusan warga", s:1}], ex:"Skor 5 terbaik: turun tangan langsung plus memenuhi kebutuhan dasar — kepemimpinan dengan teladan, bukan sekadar kata-kata."},
{id:"TKP-1182", q:"Tokoh masyarakat setempat dihormati warga tetapi bersikap pasif terhadap upaya evakuasi. Warga mengikuti sikapnya. Bagaimana Anda melibatkannya?", opts:[{t:"Mendatanginya secara khusus, menjelaskan situasi dengan hormat, dan memintanya memimpin imbauan evakuasi karena pengaruhnya besar", s:5},{t:"Meminta bantuannya lewat perangkat desa", s:4},{t:"Mengabaikannya dan mengimbau warga langsung", s:3},{t:"Mengancamnya agar kooperatif", s:2},{t:"Menyalahkannya di depan warga", s:1}], ex:"Skor 5 terbaik: pendekatan hormat yang mengakui pengaruhnya mengubah tokoh pasif jadi motor evakuasi — kearifan berkolaborasi."},
{id:"TKP-1183", q:"Listrik posko padam dan PLN sulit dihubungi. Genset posko rusak. Malam tiba dan ratusan pengungsi butuh penerangan. Apa yang Anda lakukan?", opts:[{t:"Berkoordinasi dengan PLN melalui berbagai jalur, meminjam genset dari instansi/warga, dan mengaktifkan lampu darurat sementara", s:5},{t:"Terus menghubungi PLN sampai tersambung", s:4},{t:"Membagikan lilin ke tiap tenda", s:3},{t:"Menyuruh pengungsi tidur lebih awal", s:2},{t:"Menunggu PLN datang sendiri", s:1}], ex:"Skor 5 terbaik: multi-jalur solusi (koordinasi + pinjam genset + darurat sementara) — tidak bergantung pada satu pintu."},
{id:"TKP-1184", q:"Pasokan air bersih dari PDAM terhenti akibat pipa rusak. Dinas PU butuh waktu perbaikan. Pengungsi butuh air segera. Tindakan Anda?", opts:[{t:"Berkoordinasi dengan PU untuk percepatan, mendatangkan mobil tangki air darurat, dan mengatur distribusi air secara adil", s:5},{t:"Meminta PU segera memperbaiki", s:4},{t:"Menyuruh warga mengambil air dari sungai", s:3},{t:"Menunggu perbaikan selesai", s:2},{t:"Menyalahkan PU di depan warga", s:1}], ex:"Skor 5 terbaik: solusi darurat (tangki air) sambil mendorong perbaikan permanen — kebutuhan mendesak terpenuhi tanpa menunggu."},
{id:"TKP-1185", q:"Ibu-ibu PKK menawarkan membentuk tim dapur umum gabungan, tetapi mereka butuh kompor, bahan, dan koordinasi. Sebagian petugas ragu melibatkan warga. Sikap Anda?", opts:[{t:"Menyambut dan memfasilitasi: menyediakan peralatan dan bahan, membagi tugas, serta mendampingi agar dapur umum berjalan", s:5},{t:"Mempersilakan mereka memasak sendiri", s:4},{t:"Menolak karena merepotkan koordinasi", s:3},{t:"Membiarkan tanpa dukungan", s:2},{t:"Melarang karena bukan tugas mereka", s:1}], ex:"Skor 5 terbaik: memberdayakan warga sebagai mitra (difasilitasi, bukan dilepas) melipatgandakan kapasitas dapur umum."},
{id:"TKP-1186", q:"Karang taruna menawarkan diri sebagai relawan, tetapi mereka minim pengalaman dan beberapa petugas meremehkan. Bagaimana Anda mengelola mereka?", opts:[{t:"Menerima dengan memberi briefing tugas yang sesuai kemampuan, menunjuk pendamping, dan menghargai kontribusi mereka", s:5},{t:"Menerima dan memberi tugas ringan", s:4},{t:"Menolak karena tidak berpengalaman", s:3},{t:"Menerima tetapi tidak diberi tugas jelas", s:2},{t:"Mengejek semangat mereka", s:1}], ex:"Skor 5 terbaik: pemuda adalah aset; briefing + pendampingan + penghargaan mengubah semangat mentah jadi tenaga efektif."},
{id:"TKP-1187", q:"Banyak jenazah korban gempa perlu dimakamkan segera. Keluarga berbeda agama dan adat meminta prosesi sesuai keyakinan masing-masing dalam keterbatasan. Bagaimana Anda mengoordinasikan?", opts:[{t:"Berkoordinasi dengan tokoh tiap agama/adat, menyiapkan prosesi sesuai keyakinan masing-masing keluarga, dan mengatur jadwal serta lokasi dengan tertib", s:5},{t:"Memakamkan secara massal agar cepat", s:4},{t:"Mengikuti prosesi mayoritas saja", s:3},{t:"Menyerahkan sepenuhnya ke keluarga tanpa bantuan", s:2},{t:"Menunda pemakaman sampai semua sepakat", s:1}], ex:"Skor 5 terbaik: duka setiap keluarga dihormati sesuai keyakinannya; koordinasi lintas tokoh agama menjamin tertib dan bermartabat."},
{id:"TKP-1188", q:"Kabupaten tetangga menawarkan bantuan personel dan logistik, tetapi ada gengsi di pimpinan Anda untuk menerima ('kita bisa sendiri'). Bantuan itu sangat dibutuhkan. Sikap Anda?", opts:[{t:"Menyampaikan ke pimpinan bahwa menerima bantuan adalah demi korban, mengusulkan mekanisme penerimaan yang tertib dan terdokumentasi", s:5},{t:"Menerima bantuan secara diam-diam", s:4},{t:"Menolak demi menjaga gengsi daerah", s:3},{t:"Membiarkan tawaran berlalu", s:2},{t:"Menjelek-jelekkan daerah tetangga", s:1}], ex:"Skor 5 terbaik: kepentingan korban di atas gengsi; advokasi santun ke pimpinan plus mekanisme tertib membuat bantuan diterima terhormat."},
{id:"TKP-1189", q:"TNI menawarkan membangun huntara bersama, tetapi butuh lahan dan dukungan administrasi dari pemda yang lambat. Warga sudah tidak sabar. Apa yang Anda lakukan?", opts:[{t:"Aktif mempercepat proses administrasi dan penyiapan lahan, berkoordinasi intensif agar pembangunan bisa segera dimulai", s:5},{t:"Menunggu proses administrasi selesai", s:4},{t:"Meminta TNI menunggu", s:3},{t:"Menyalahkan bagian administrasi yang lambat", s:2},{t:"Membatalkan kerja sama dengan TNI", s:1}], ex:"Skor 5 terbaik: menjadi akselerator birokrasi — proaktif mempercepat proses agar niat baik TNI segera terwujud untuk warga."},
{id:"TKP-1190", q:"Relawan lokal yang sudah bekerja seminggu kelelahan dan mulai pulang satu per satu, padahal kebutuhan masih tinggi. Bagaimana Anda mempertahankan mereka?", opts:[{t:"Mengatur shift agar ada waktu istirahat, memberi apresiasi terbuka, memenuhi kebutuhan dasar mereka, dan merekrut relawan pengganti bertahap", s:5},{t:"Memohon mereka bertahan sedikit lagi", s:4},{t:"Menjanjikan imbalan", s:3},{t:"Membiarkan mereka pulang", s:2},{t:"Memarahi yang pulang duluan", s:1}], ex:"Skor 5 terbaik: relawan dijaga dengan sistem (shift, apresiasi, regenerasi) — keberlanjutan, bukan pemerasan semangat."},
{id:"TKP-1191", q:"Anda kewalahan menangani tumpukan tugas di posko: pendataan, distribusi, dan koordinasi menumpuk. Kualitas kerja mulai menurun. Apa yang Anda lakukan?", opts:[{t:"Memprioritaskan tugas paling kritis, mendelegasikan sebagian ke rekan/relawan dengan instruksi jelas, dan melaporkan beban ke koordinator", s:5},{t:"Mengerjakan satu per satu sampai selesai", s:4},{t:"Meminta rekan mengambil alih semuanya", s:3},{t:"Mengerjakan asal-asalan agar cepat selesai", s:2},{t:"Meninggalkan tugas yang menumpuk", s:1}], ex:"Skor 5 terbaik: prioritas + delegasi jelas + komunikasi ke koordinator — mengelola beban secara profesional, bukan heroik sendirian."},
{id:"TKP-1192", q:"Anda ditugaskan memimpin tim evakuasi tetapi tidak menguasai medan dan teknik evakuasi air. Tim menunggu instruksi Anda. Sikap Anda?", opts:[{t:"Jujur mengakui keterbatasan, meminta anggota tim yang berpengalaman memimpin teknis, dan Anda fokus pada koordinasi dan dukungan", s:5},{t:"Memimpin sambil belajar dari anggota tim", s:4},{t:"Memimpin dengan instruksi asal", s:3},{t:"Menolak memimpin", s:2},{t:"Berpura-pura menguasai dan memberi perintah ngawur", s:1}], ex:"Skor 5 terbaik: kejujuran tentang keterbatasan plus pendelegasian ke yang ahli — keselamatan tim dan korban di atas ego jabatan."},
{id:"TKP-1193", q:"Seorang relawan bekerja sangat keras setiap hari tanpa pamrih. Tidak ada yang mengapresiasinya dan ia mulai terlihat lelah batin. Apa yang Anda lakukan?", opts:[{t:"Memberi apresiasi terbuka di depan tim, memastikan ia mendapat istirahat cukup, dan mengusulkan penghargaan resmi", s:5},{t:"Mengucapkan terima kasih secara pribadi", s:4},{t:"Menganggap itu kewajibannya sebagai relawan", s:3},{t:"Membiarkan karena semua juga lelah", s:2},{t:"Menambah bebannya karena ia mampu", s:1}], ex:"Skor 5 terbaik: apresiasi terbuka + istirahat + penghargaan resmi — merawat relawan agar dedikasinya berkelanjutan."},
{id:"TKP-1194", q:"Dua kelompok relawan berselisih soal metode distribusi hingga hampir adu fisik di depan pengungsi. Situasi memalukan dan mengganggu. Tindakan Anda?", opts:[{t:"Segera melerai, memisahkan keduanya, memfasilitasi dialog untuk menyepakati metode, dan menegaskan kode etik relawan", s:5},{t:"Melerai dan meminta keduanya tenang", s:4},{t:"Memihak kelompok yang metodenya benar", s:3},{t:"Mengusir kedua kelompok", s:2},{t:"Membiarkan mereka menyelesaikan sendiri", s:1}], ex:"Skor 5 terbaik: lerai + fasilitasi kesepakatan + tegakkan kode etik — konflik diselesaikan tanpa mengorbankan pelayanan."},
{id:"TKP-1195", q:"Media massa ingin menyiarkan informasi resmi tentang kebutuhan posko agar bantuan tepat sasaran. Namun ada kekhawatiran informasi disalahartikan. Sikap Anda?", opts:[{t:"Bekerja sama dengan media: menyiapkan data kebutuhan yang akurat dan terverifikasi, menunjuk juru bicara, dan update berkala", s:5},{t:"Memberi data seadanya ke media", s:4},{t:"Menolak semua peliputan", s:3},{t:"Membiarkan media mencari info sendiri", s:2},{t:"Memberi info tanpa verifikasi", s:1}], ex:"Skor 5 terbaik: kemitraan media yang dikelola (data akurat + juru bicara) mengubah publikasi jadi magnet bantuan tepat sasaran."},
{id:"TKP-1196", q:"Basarnas meminta data peta dan jumlah warga di zona bahaya untuk operasi evakuasi, tetapi data Anda belum lengkap. Operasi tidak bisa menunggu. Apa yang Anda lakukan?", opts:[{t:"Menyerahkan data terbaik yang ada disertai catatan kekurangannya, sambil terus melengkapi dan mengoordinasikan pemandu lokal", s:5},{t:"Menyerahkan data seadanya", s:4},{t:"Menunggu data lengkap baru diserahkan", s:3},{t:"Menolak memberi data yang belum lengkap", s:2},{t:"Membuat data perkiraan", s:1}], ex:"Skor 5 terbaik: data terbaik + catatan keterbatasan + pemandu lokal — operasi penyelamatan jalan dengan informasi jujur."},
{id:"TKP-1197", q:"Tim asesmen kerusakan dari berbagai instansi datang sendiri-sendiri dengan format berbeda, membingungkan warga yang didata berulang kali. Bagaimana Anda menertibkan?", opts:[{t:"Mengusulkan tim asesmen gabungan satu pintu dengan format standar, jadwal terkoordinasi, dan sosialisasi ke warga", s:5},{t:"Meminta tiap tim berkoordinasi dulu", s:4},{t:"Membiarkan karena tiap instansi butuh datanya", s:3},{t:"Melarang tim yang datang belakangan", s:2},{t:"Menyalahkan warga yang mengeluh", s:1}], ex:"Skor 5 terbaik: asesmen satu pintu berformat standar — efisien bagi instansi, tidak membebani warga."},
{id:"TKP-1198", q:"Setiap posko membuat laporan harian dengan format bebas sehingga sulit digabungkan menjadi laporan kabupaten. Pimpinan membutuhkan data cepat. Solusi Anda?", opts:[{t:"Membuat template laporan harian standar yang sederhana, mensosialisasikan ke semua posko, dan menetapkan batas waktu pengiriman", s:5},{t:"Meminta posko mengirim data mentah untuk diolah pusat", s:4},{t:"Menggabungkan manual setiap hari", s:3},{t:"Melaporkan perkiraan saja", s:2},{t:"Tidak membuat laporan gabungan", s:1}], ex:"Skor 5 terbaik: standardisasi template sederhana di hulu menyelesaikan masalah rekap di hilir secara permanen."},
{id:"TKP-1199", q:"Belum ada rencana kontinjensi untuk banjir susulan padahal musim hujan masih panjang. Pimpinan belum memikirkannya. Apa inisiatif Anda?", opts:[{t:"Menyusun draf rencana kontinjensi (skenario, kebutuhan, pembagian tugas) dan mengajukannya ke pimpinan untuk dibahas", s:5},{t:"Mengusulkan ke pimpinan agar dibuat rencana", s:4},{t:"Menunggu instruksi pimpinan", s:3},{t:"Menganggap bencana tidak akan terulang", s:2},{t:"Tidak peduli karena bukan tugas Anda", s:1}], ex:"Skor 5 terbaik: inisiatif menyusun draf konkret — antisipatif, bukan sekadar mengusulkan."},
{id:"TKP-1200", q:"Operasi tanggap darurat selesai. Tim kelelahan dan ada ketegangan yang belum terselesaikan. Pimpinan langsung membubarkan tim tanpa evaluasi. Sikap Anda?", opts:[{t:"Mengusulkan debriefing singkat: apresiasi, evaluasi pelajaran, dan penyelesaian ketegangan agar tim bubar dengan baik", s:5},{t:"Mengadakan syukuran kecil dengan tim", s:4},{t:"Mengikuti pembubaran begitu saja", s:3},{t:"Menyimpan uneg-uneg sendiri", s:2},{t:"Menyebarkan keluhan ke tim lain", s:1}], ex:"Skor 5 terbaik: debriefing menutup operasi dengan pembelajaran dan rekonsiliasi — tim bubar utuh, pelajaran terdokumentasi."},
{id:"TKP-1201", q:"Di satu tenda besar pengungsian bercampur warga dari suku dan agama berbeda. Muncul gesekan kecil soal kebiasaan dan jadwal kegiatan. Bagaimana Anda mengelola keberagaman ini?", opts:[{t:"Memfasilitasi kesepakatan bersama tentang aturan tenda (jadwal, kebersihan, toleransi), melibatkan perwakilan tiap kelompok", s:5},{t:"Memisahkan tenda berdasarkan suku/agama", s:4},{t:"Mengimbau semua saling menghormati", s:3},{t:"Membiarkan gesekan reda sendiri", s:2},{t:"Memihak kelompok mayoritas", s:1}], ex:"Skor 5 terbaik: aturan bersama yang disepakati perwakilan tiap kelompok — keberagaman dikelola, bukan dipisah atau dibiarkan."},
{id:"TKP-1202", q:"Dapur umum hanya menyediakan satu jenis menu yang tidak bisa dimakan sebagian pengungsi karena pantangan agama/kesehatan. Mereka protes. Tindakan Anda?", opts:[{t:"Menyesuaikan menu dengan menyediakan alternatif (misal menu non-daging), mendata kebutuhan khusus, dan melibatkan perwakilan pengungsi", s:5},{t:"Membuatkan menu khusus bagi yang berpantangan", s:4},{t:"Menyuruh mereka makan seadanya", s:3},{t:"Menganggap mereka terlalu menuntut", s:2},{t:"Mengabaikan protes tersebut", s:1}], ex:"Skor 5 terbaik: pendataan kebutuhan khusus + menu alternatif — pelayanan inklusif menghormati keyakinan setiap pengungsi."},
{id:"TKP-1203", q:"Waktu salat tiba tetapi tidak ada ruang ibadah di posko. Sebagian pengungsi muslim kebingungan. Apa yang Anda lakukan?", opts:[{t:"Segera menyiapkan ruang salat darurat (tenda/ruang khusus) lengkap dengan sarana wudu sederhana", s:5},{t:"Menunjukkan area kosong yang bisa dipakai salat", s:4},{t:"Menyarankan salat di tenda masing-masing", s:3},{t:"Menganggap ibadah urusan pribadi", s:2},{t:"Melarang kegiatan ibadah berkelompok di posko", s:1}], ex:"Skor 5 terbaik: penyediaan ruang ibadah adalah penghormatan hak beragama; difasilitasi, bukan sekadar dipersilakan."},
{id:"TKP-1204", q:"Jenazah korban bencana dari keluarga non-muslim perlu penanganan sesuai keyakinannya, tetapi petugas hanya paham tata cara muslim. Keluarga khawatir. Bagaimana Anda menangani?", opts:[{t:"Berkoordinasi dengan tokoh/pemuka agama yang bersangkutan untuk memandu prosesi sesuai keyakinan keluarga", s:5},{t:"Meminta keluarga memandu petugas", s:4},{t:"Menangani dengan tata cara umum saja", s:3},{t:"Menangani dengan tata cara mayoritas", s:2},{t:"Menunda penanganan sampai ada yang paham", s:1}], ex:"Skor 5 terbaik: melibatkan pemuka agama yang berwenang menjamin prosesi sesuai keyakinan — penghormatan di saat duka."},
{id:"TKP-1205", q:"Adat setempat mengharuskan prosesi tertentu sebelum jenazah korban longsor dimakamkan, tetapi tim ingin segera memakamkan karena alasan kesehatan. Terjadi ketegangan. Sikap Anda?", opts:[{t:"Berdialog dengan tetua adat mencari jalan tengah: prosesi inti yang singkat dan khidmat tetap dilaksanakan dengan tetap menjaga aspek kesehatan", s:5},{t:"Mengikuti adat sepenuhnya meski tertunda", s:4},{t:"Memakamkan segera demi kesehatan", s:3},{t:"Mengabaikan adat karena situasi darurat", s:2},{t:"Memaksa tim mengikuti semua prosesi adat", s:1}], ex:"Skor 5 terbaik: jalan tengah yang menghormati adat sekaligus menjaga kesehatan — dialog, bukan pemaksaan salah satu pihak."},
{id:"TKP-1206", q:"Banyak lansia pengungsi hanya bisa berbahasa daerah dan tidak paham pengumuman berbahasa Indonesia. Informasi penting tidak sampai ke mereka. Solusi Anda?", opts:[{t:"Melibatkan relawan/penerjemah lokal, membuat pengumuman dwibahasa, dan menyampaikan langsung dari tenda ke tenda", s:5},{t:"Meminta keluarga muda menerjemahkan", s:4},{t:"Mengulang pengumuman lebih keras", s:3},{t:"Membiarkan karena mayoritas paham", s:2},{t:"Menganggap itu bukan masalah", s:1}], ex:"Skor 5 terbaik: komunikasi dwibahasa plus jemput bola memastikan lansia tidak tertinggal informasi penting."},
{id:"TKP-1207", q:"Sebagian warga menolak menerima bantuan dari organisasi kemanusiaan berbasis agama tertentu karena perbedaan keyakinan, padahal mereka sangat membutuhkan. Bagaimana Anda menyikapi?", opts:[{t:"Menjelaskan bahwa bantuan disalurkan lewat posko resmi untuk semua tanpa memandang latar belakang, dan memastikan penyalurannya netral", s:5},{t:"Mencarikan bantuan dari sumber lain", s:4},{t:"Membujuk mereka menerima saja", s:3},{t:"Membiarkan mereka menolak", s:2},{t:"Menyalahkan mereka kolot", s:1}], ex:"Skor 5 terbaik: penyaluran lewat posko resmi yang netral menghilangkan sekat — bantuan kemanusiaan untuk semua."},
{id:"TKP-1208", q:"Warga lintas agama bergotong royong membersihkan rumah ibadah yang rusak akibat gempa. Momen ini bisa memperkuat kerukunan. Apa yang Anda lakukan?", opts:[{t:"Mendukung dan memfasilitasi kegiatan tersebut, mendokumentasikan sebagai teladan kerukunan, dan mengembangkannya ke kegiatan bersama lain", s:5},{t:"Mendukung kegiatan mereka", s:4},{t:"Membiarkan berjalan alami", s:3},{t:"Melarang karena rawan konflik", s:2},{t:"Menganggap tidak ada istimewanya", s:1}], ex:"Skor 5 terbaik: difasilitasi dan dikembangkan — momen kerukunan di tengah bencana adalah modal sosial yang harus dirawat."},
{id:"TKP-1209", q:"Anak-anak pengungsi dari latar berbeda bermain bersama tanpa sekat, tetapi sebagian orang tua melarang anaknya bergaul dengan anak dari kelompok tertentu. Sikap Anda?", opts:[{t:"Mengadakan kegiatan anak bersama yang menyenangkan dan mengedukasi orang tua tentang indahnya kebersamaan sejak dini", s:5},{t:"Membiarkan anak-anak bermain bersama", s:4},{t:"Mengikuti keinginan orang tua", s:3},{t:"Memisahkan area bermain", s:2},{t:"Mendukung pelarangan orang tua", s:1}], ex:"Skor 5 terbaik: kegiatan bersama plus edukasi orang tua — menumbuhkan toleransi sejak dini, bukan mengikuti prasangka."},
{id:"TKP-1210", q:"Pengambilan keputusan evakuasi di desa adat harus melalui musyawarah dengan pemangku adat, tetapi waktu mendesak. Aparat ingin bertindak cepat sepihak. Bagaimana Anda menjembatani?", opts:[{t:"Segera berkoordinasi kilat dengan pemangku adat, menjelaskan urgensi, dan meminta restu/keputusan cepat sesuai mekanisme adat yang disederhanakan", s:5},{t:"Bertindak sepihak demi keselamatan", s:4},{t:"Menunggu musyawarah adat selesai", s:3},{t:"Mengabaikan peran pemangku adat", s:2},{t:"Memaksa pemangku adat menyetujui", s:1}], ex:"Skor 5 terbaik: koordinasi kilat yang menghormati mekanisme adat — keputusan cepat tetap legitimate di mata warga."},
{id:"TKP-1211", q:"Warga ingin mengadakan selamatan/doa bersama pasca-bencana sesuai tradisi, tetapi melibatkan banyak orang di tengah keterbatasan posko. Sikap Anda?", opts:[{t:"Memfasilitasi dengan pengaturan yang tertib (waktu, tempat, pembagian tugas) dan mengajak semua unsur berpartisipasi", s:5},{t:"Mempersilakan warga mengadakan sendiri", s:4},{t:"Melarang karena mengganggu ketertiban", s:3},{t:"Membiarkan tanpa pengaturan", s:2},{t:"Mengejek tradisi tersebut", s:1}], ex:"Skor 5 terbaik: tradisi duka dan syukur difasilitasi tertib — pemulihan psikososial warga lewat budayanya sendiri."},
{id:"TKP-1212", q:"Tetua adat melarang pembangunan huntara di lokasi yang dipilih pemerintah karena dianggap tanah terlarang menurut adat. Padahal lahannya strategis. Bagaimana Anda menangani?", opts:[{t:"Berdialog dengan tetua adat memahami alasannya, mencari alternatif lokasi bersama, dan melibatkan mereka dalam penentuan lokasi", s:5},{t:"Mencari lokasi lain tanpa dialog", s:4},{t:"Tetap membangun karena keputusan pemerintah", s:3},{t:"Mengabaikan larangan adat", s:2},{t:"Mengancam tetua adat", s:1}], ex:"Skor 5 terbaik: dialog memahami + mencari alternatif bersama — menghormati adat tanpa mengorbankan kebutuhan huntara."},
{id:"TKP-1213", q:"Pengungsi perempuan mengeluh tidak ada ruang privasi: mereka berganti pakaian dan menyusui di tenda campur. Sebagian merasa tidak aman malam hari. Tindakan Anda?", opts:[{t:"Segera membuat bilik privasi khusus perempuan, mengatur penerangan dan ronda malam, serta menunjuk petugas perempuan", s:5},{t:"Membuat sekat kain sederhana di tenda", s:4},{t:"Menyarankan mereka bergantian memakai tenda", s:3},{t:"Menganggap kondisi darurat memang begitu", s:2},{t:"Mengabaikan keluhan tersebut", s:1}], ex:"Skor 5 terbaik: privasi dan keamanan perempuan adalah kebutuhan dasar; bilik khusus + ronda + petugas perempuan menyelesaikannya menyeluruh."},
{id:"TKP-1214", q:"Ibu menyusui di pengungsian kesulitan karena tidak ada tempat tenang dan asupan gizinya kurang. Bayinya rewel. Apa yang Anda lakukan?", opts:[{t:"Menyediakan ruang menyusui yang nyaman dan memastikan ibu mendapat tambahan gizi (makanan bergizi, susu) dari logistik posko", s:5},{t:"Memberi makanan tambahan untuk ibu", s:4},{t:"Menyarankan menyusui di tenda saja", s:3},{t:"Menganggap hal biasa di pengungsian", s:2},{t:"Mengabaikan", s:1}], ex:"Skor 5 terbaik: ruang nyaman + gizi ibu = bayi sehat; perhatian pada 1000 hari pertama kehidupan bahkan dalam bencana."},
{id:"TKP-1215", q:"Seorang lansia bersikeras ingin pulang ke rumahnya yang rusak berat karena 'lebih baik mati di rumah sendiri'. Keluarganya meminta Anda membujuk. Tindakan Anda?", opts:[{t:"Berdialog empatik dengannya, memahami alasannya, menjelaskan bahaya, dan menawarkan solusi (tinggal sementara dengan keluarga/kunjungan terjadwal)", s:5},{t:"Membujuknya agar tetap di pengungsian", s:4},{t:"Membiarkan pulang karena itu keinginannya", s:3},{t:"Memaksanya tetap di pengungsian", s:2},{t:"Mengabaikan permintaan keluarga", s:1}], ex:"Skor 5 terbaik: dialog empatik yang menggali alasan plus solusi konkret — menghormati martabat lansia tanpa mengorbankan keselamatannya."},
{id:"TKP-1216", q:"Anak yatim piatu korban gempa diperebutkan: keluarga jauh yang jarang kontak ingin mengasuh demi santunan, sementara tetangga dekat yang sayang padanya tidak mampu. Sebagai petugas sosial, apa pertimbangan Anda?", opts:[{t:"Mengutamakan kepentingan terbaik anak melalui asesmen (kasih sayang, kemampuan, lingkungan), bukan sekadar hubungan darah atau materi", s:5},{t:"Menyerahkan ke keluarga yang hubungan darahnya terdekat", s:4},{t:"Menitipkan ke panti asuhan", s:3},{t:"Membiarkan mereka berebut", s:2},{t:"Memutuskan berdasarkan siapa yang datang duluan", s:1}], ex:"Skor 5 terbaik: asesmen kepentingan terbaik anak — kasih sayang dan pengasuhan yang layak mengalahkan sekadar hubungan darah."},
{id:"TKP-1217", q:"Posko pengungsian tidak ramah bagi pengguna kursi roda: jalan becek, tenda bertingkat, MCK jauh. Seorang penyandang disabilitas kesulitan beraktivitas. Tindakan Anda?", opts:[{t:"Membuat jalur dan area khusus yang mudah diakses, menempatkannya di tenda terdekat fasilitas, dan menugaskan pendamping", s:5},{t:"Memindahkannya ke tenda terdekat MCK", s:4},{t:"Meminta keluarganya membantu", s:3},{t:"Menyarankan pulang ke rumah saudara", s:2},{t:"Menganggap kondisi darurat tidak bisa ideal", s:1}], ex:"Skor 5 terbaik: aksesibilitas adalah hak; penyesuaian area + pendamping memastikan disabilitas tetap bermartabat di pengungsian."},
{id:"TKP-1218", q:"Kelompok minoritas di desa terdampak merasa selalu terlewat dalam pendataan bantuan. Mereka curiga ada diskriminasi. Bagaimana Anda menangani?", opts:[{t:"Melakukan pendataan ulang yang inklusif dengan melibatkan perwakilan mereka, memastikan tidak ada yang terlewat, dan transparan soal kriteria", s:5},{t:"Mendata ulang wilayah mereka", s:4},{t:"Menjelaskan tidak ada diskriminasi", s:3},{t:"Menganggap mereka terlalu sensitif", s:2},{t:"Mengabaikan kecurigaan mereka", s:1}], ex:"Skor 5 terbaik: pendataan ulang inklusif dengan pelibatan perwakilan — bukti nyata, bukan sekadar bantahan."},
{id:"TKP-1219", q:"Jadwal kegiatan posko (distribusi, gotong royong) sering berbenturan dengan waktu ibadah. Sebagian pengungsi terpaksa memilih. Solusi Anda?", opts:[{t:"Menyusun jadwal kegiatan yang menghindari waktu-waktu ibadah semua agama dan mensosialisasikannya", s:5},{t:"Menggeser jadwal yang bentrok saja", s:4},{t:"Mempersilakan yang ibadah izin", s:3},{t:"Menganggap ibadah bisa disesuaikan", s:2},{t:"Mengabaikan karena jadwal sudah padat", s:1}], ex:"Skor 5 terbaik: jadwal yang sejak awal menghormati waktu ibadah semua agama — toleransi yang terencana, bukan tambal sulam."},
{id:"TKP-1220", q:"Hari raya keagamaan tiba saat warga masih di pengungsian. Mereka sedih tidak bisa merayakan seperti biasa. Apa yang Anda lakukan?", opts:[{t:"Memfasilitasi perayaan sederhana yang khidmat (tempat ibadah, hidangan khusus, silaturahmi) agar mereka tetap bisa merayakan", s:5},{t:"Mengucapkan selamat hari raya", s:4},{t:"Membiarkan mereka merayakan sendiri", s:3},{t:"Melarang perayaan karena keterbatasan", s:2},{t:"Menganggap perayaan tidak penting saat bencana", s:1}], ex:"Skor 5 terbaik: memfasilitasi perayaan di tengah keterbatasan menjaga ketahanan batin dan identitas komunitas pengungsi."},
{id:"TKP-1221", q:"Muncul stigma di masyarakat bahwa pengungsi 'pemalas' dan 'hanya menunggu bantuan'. Pengungsi tersinggung dan menarik diri dari kegiatan. Bagaimana Anda mengatasi stigma ini?", opts:[{t:"Mengedukasi publik lewat contoh nyata kontribusi pengungsi (gotong royong, dapur umum) dan melibatkan mereka dalam pemulihan", s:5},{t:"Membela pengungsi di depan umum", s:4},{t:"Mengabaikan stigma tersebut", s:3},{t:"Menyalahkan masyarakat yang menstigma", s:2},{t:"Membenarkan stigma itu", s:1}], ex:"Skor 5 terbaik: melawan stigma dengan bukti kontribusi nyata plus pelibatan — memulihkan martabat lewat aksi."},
{id:"TKP-1222", q:"Tetua desa mengenali tanda-tanda alam sebelum banjir (perilaku hewan, perubahan air sungai) dan ingin berbagi pengetahuan ini. Sebagian petugas menganggapnya takhayul. Sikap Anda?", opts:[{t:"Menghargai kearifan lokal tersebut, mendokumentasikannya, dan mengombinasikannya dengan sistem peringatan dini modern", s:5},{t:"Mendengarkan penjelasannya", s:4},{t:"Mengabaikan karena tidak ilmiah", s:3},{t:"Menertawakan di depan warga", s:2},{t:"Melarang menyebarkan 'takhayul'", s:1}], ex:"Skor 5 terbaik: kearifan lokal adalah sistem peringatan dini yang teruji zaman; dikombinasikan dengan sains jadi mitigasi yang kuat."},
{id:"TKP-1223", q:"Seorang ibu hamil di posko lebih percaya pada paraji (dukun beranak) daripada bidan posko, dan menolak pemeriksaan medis. Kondisinya berisiko. Bagaimana Anda menangani?", opts:[{t:"Merangkul paraji sebagai mitra: memintanya mendampingi dan meyakinkan ibu untuk tetap diperiksa bidan, menggabungkan keduanya", s:5},{t:"Memaksa ibu diperiksa bidan", s:4},{t:"Membiarkan ditangani paraji saja", s:3},{t:"Melarang paraji masuk posko", s:2},{t:"Mengabaikan karena pilihannya sendiri", s:1}], ex:"Skor 5 terbaik: merangkul tokoh kepercayaan sebagai jembatan — keselamatan ibu tercapai tanpa merendahkan budaya."},
{id:"TKP-1224", q:"Lokasi huntara yang direncanakan ternyata tanah ulayat masyarakat adat yang keberatan. Di sisi lain warga butuh hunian segera. Bagaimana Anda menyelesaikan?", opts:[{t:"Memfasilitasi musyawarah antara pemerintah dan masyarakat adat: mencari kesepakatan (kompensasi, lokasi alternatif, atau izin bersyarat)", s:5},{t:"Mencari lokasi lain", s:4},{t:"Tetap membangun demi kepentingan umum", s:3},{t:"Mengabaikan keberatan adat", s:2},{t:"Memaksa dengan aparat", s:1}], ex:"Skor 5 terbaik: musyawarah mencari titik temu menghormati hak ulayat sekaligus memenuhi kebutuhan hunian — solusi bermartabat."},
{id:"TKP-1225", q:"Seorang pengungsi tunarungu tidak memahami pengumuman dan instruksi evakuasi. Ia tertinggal informasi penting berulang kali. Tindakan Anda?", opts:[{t:"Menugaskan relawan pendamping khusus, menggunakan bahasa isyarat/tulisan/visual, dan memastikan ia selalu terinformasi", s:5},{t:"Menuliskan pengumuman untuknya", s:4},{t:"Meminta keluarganya menjelaskan", s:3},{t:"Menganggap ia bisa membaca situasi", s:2},{t:"Mengabaikan", s:1}], ex:"Skor 5 terbaik: pendamping khusus plus komunikasi visual memastikan hak informasi difabel terpenuhi penuh."},
{id:"TKP-1226", q:"Donatur ingin berfoto dengan anak-anak pengungsi sambil menyerahkan bantuan untuk publikasi. Anak-anak tampak tidak nyaman. Bagaimana Anda melindungi mereka?", opts:[{t:"Mengatur sesi dokumentasi yang etis: izin orang tua, tidak mengeksploitasi kesedihan anak, dan mengutamakan kenyamanan mereka", s:5},{t:"Meminta donatur tidak memaksa anak berfoto", s:4},{t:"Membiarkan karena donatur berhak dokumentasi", s:3},{t:"Menyuruh anak-anak tersenyum untuk foto", s:2},{t:"Menjadikan anak sebagai properti foto", s:1}], ex:"Skor 5 terbaik: dokumentasi etis melindungi martabat anak — bantuan tidak boleh menukar harga diri penerima."},
{id:"TKP-1227", q:"Petugas posko melayani pengungsi 'orang penting' lebih dulu sementara warga biasa antre lama. Praktik ini terlihat jelas. Sikap Anda?", opts:[{t:"Menegur praktik diskriminatif tersebut dan memastikan pelayanan berdasarkan urutan dan prioritas kebutuhan, bukan status sosial", s:5},{t:"Mengingatkan agar adil", s:4},{t:"Membiarkan karena orang penting memang sibuk", s:3},{t:"Ikut melayani orang penting duluan", s:2},{t:"Menganggap wajar", s:1}], ex:"Skor 5 terbaik: di posko bencana semua setara; pelayanan berbasis kebutuhan menegakkan keadilan."},
{id:"TKP-1228", q:"Sebuah keluarga kehilangan seluruh harta benda dalam kebakaran: rumah, usaha, dan tabungan. Mereka syok dan putus asa, merasa hidupnya berakhir. Bagaimana Anda mendampingi?", opts:[{t:"Mendampingi dengan empati, membantu mengakses seluruh bantuan yang berhak diterima, dan menghubungkan dengan dukungan psikososial serta peluang bangkit", s:5},{t:"Memberi semangat agar tabah", s:4},{t:"Menyalurkan bantuan standar", s:3},{t:"Menyuruh mereka ikhlas dan sabar", s:2},{t:"Menganggap berlebihan, yang penting selamat", s:1}], ex:"Skor 5 terbaik: empati + akses bantuan maksimal + dukungan psikososial + jalan bangkit — pendampingan menyeluruh memulihkan harapan."},
{id:"TKP-1229", q:"Tim psikolog menawarkan trauma healing massal, tetapi sebagian korban menolak karena belum siap membuka luka dan merasa dipaksa. Bagaimana Anda menyikapi?", opts:[{t:"Menghormati kesiapan tiap korban: menawarkan layanan sukarela bertahap, menyediakan ruang aman, tanpa paksaan", s:5},{t:"Menganjurkan mereka ikut perlahan", s:4},{t:"Memaksa demi kebaikan mereka", s:3},{t:"Membatalkan program", s:2},{t:"Mengejek yang menolak cengeng", s:1}], ex:"Skor 5 terbaik: pemulihan trauma tidak bisa dipaksa; layanan sukarela bertahap menghormati proses tiap individu."},
{id:"TKP-1230", q:"Pasca-bencana, semangat gotong royong warga menurun: masing-masing sibuk membangun rumahnya sendiri. Solidaritas yang dulu kuat memudar. Apa yang Anda lakukan?", opts:[{t:"Menginisiasi kegiatan gotong royong rutin yang bermanfaat bersama (fasilitas umum), memberi apresiasi, dan menumbuhkan kembali kebanggaan kolektif", s:5},{t:"Mengajak warga gotong royong", s:4},{t:"Membiarkan karena wajar", s:3},{t:"Menyalahkan warga individualis", s:2},{t:"Tidak peduli", s:1}], ex:"Skor 5 terbaik: memupuk kembali modal sosial lewat kegiatan bersama yang nyata manfaatnya — solidaritas dirawat, bukan dinasihati."},
{id:"TKP-1231", q:"Posko beralih ke pendataan pengungsi digital via aplikasi, tetapi banyak petugas gagap teknologi dan antrean pendataan macet. Apa yang Anda lakukan?", opts:[{t:"Mengadakan briefing cepat, menunjuk petugas pendamping di tiap loket, dan menyiapkan formulir manual cadangan agar antrean tetap jalan", s:5},{t:"Meminta petugas belajar sendiri", s:4},{t:"Kembali ke pendataan manual sepenuhnya", s:3},{t:"Membiarkan antrean macet", s:2},{t:"Menyalahkan petugas yang gagap teknologi", s:1}], ex:"Skor 5 terbaik: transisi digital didampingi (briefing + pendamping + cadangan manual) — teknologi membantu, bukan menghambat."},
{id:"TKP-1232", q:"Server aplikasi pendataan korban down di tengah proses verifikasi bantuan. Ratusan warga sudah antre. Teknisi belum bisa dihubungi. Tindakan Anda?", opts:[{t:"Beralih ke sistem manual sementara yang tertata (nomor antre, formulir kertas), mencatat rapi untuk diinput nanti, sambil terus menghubungi teknisi", s:5},{t:"Menunggu server pulih", s:4},{t:"Menyuruh warga pulang dan kembali besok", s:3},{t:"Mendata asal-asalan tanpa sistem", s:2},{t:"Membatalkan verifikasi hari itu", s:1}], ex:"Skor 5 terbaik: rencana cadangan manual yang tertata menjaga layanan tetap jalan saat teknologi gagal."},
{id:"TKP-1233", q:"Beredar hoaks di grup WhatsApp bahwa bantuan tahap berikutnya dibatalkan. Warga panik dan menyerbu posko menuntut kejelasan. Apa yang Anda lakukan?", opts:[{t:"Segera membuat klarifikasi resmi (pengumuman, media sosial resmi, grup WA), menjelaskan fakta, dan mengimbau verifikasi info", s:5},{t:"Menjelaskan ke warga yang datang bahwa itu hoaks", s:4},{t:"Mengabaikan karena pasti reda sendiri", s:3},{t:"Ikut panik dan ikut menyerbu posko", s:2},{t:"Menyalahkan penyebar hoaks tanpa klarifikasi", s:1}], ex:"Skor 5 terbaik: klarifikasi resmi cepat multi-saluran memutus kepanikan; edukasi verifikasi mencegah hoaks berikutnya."},
{id:"TKP-1234", q:"Koordinasi posko kacau karena informasi tersebar di banyak grup chat pribadi. Instruksi penting tenggelam. Bagaimana Anda menertibkan komunikasi digital?", opts:[{t:"Membuat satu grup koordinasi resmi dengan aturan main (topik, format laporan, jam update) dan menunjuk admin", s:5},{t:"Membuat grup baru tanpa aturan", s:4},{t:"Menggunakan grup yang ada seadanya", s:3},{t:"Melarang semua grup chat", s:2},{t:"Membiarkan kekacauan", s:1}], ex:"Skor 5 terbaik: satu kanal resmi beraturan mengubah kebisingan chat jadi alur informasi yang efektif."},
{id:"TKP-1235", q:"Tim Anda ingin membuat peta digital sebaran korban dan kebutuhan (GIS) agar distribusi tepat sasaran, tetapi tidak ada yang bisa mengoperasikannya. Apa langkah Anda?", opts:[{t:"Mempelajari dasarnya bersama tim lewat tutorial/pelatihan singkat, atau berkoordinasi dengan dinas yang memiliki SDM GIS", s:5},{t:"Meminta bantuan dinas lain", s:4},{t:"Membatalkan rencana peta digital", s:3},{t:"Membuat peta manual seadanya", s:2},{t:"Menganggap tidak perlu", s:1}], ex:"Skor 5 terbaik: keterbatasan diatasi dengan belajar atau kolaborasi — peta kebutuhan membuat bantuan presisi."},
{id:"TKP-1236", q:"Tim relawan mengusulkan memakai drone untuk memetakan desa terisolir pasca-longsor. Sebagian khawatir soal privasi dan perizinan. Sikap Anda?", opts:[{t:"Mendukung dengan memastikan izin dan etika penggunaan (hanya area bencana, tidak merekam privat), hasilnya untuk kepentingan evakuasi", s:5},{t:"Mendukung tanpa pengaturan", s:4},{t:"Menolak karena ribet perizinan", s:3},{t:"Melarang total penggunaan drone", s:2},{t:"Membiarkan tanpa pengawasan", s:1}], ex:"Skor 5 terbaik: teknologi dimanfaatkan dengan rambu etika dan izin — manfaat maksimal, risiko privasi terkendali."},
{id:"TKP-1237", q:"Database pengungsi digital berisi data sensitif (NIK, kondisi kesehatan). Seorang staf ingin mengaksesnya untuk 'penelitian' pribadi. Bagaimana Anda menyikapi?", opts:[{t:"Menolak dan menjelaskan data hanya untuk kepentingan penanganan bencana sesuai aturan perlindungan data pribadi", s:5},{t:"Menolak dengan halus", s:4},{t:"Memberi data yang disamarkan", s:3},{t:"Mengizinkan karena sesama staf", s:2},{t:"Memberi akses penuh", s:1}], ex:"Skor 5 terbaik: penolakan tegas berbasis aturan perlindungan data — data korban bukan bahan penelitian pribadi."},
{id:"TKP-1238", q:"Pemerintah daerah ingin penyaluran bansos lewat transfer bank/QRIS agar transparan, tetapi banyak penerima lansia tidak punya rekening dan gagap digital. Bagaimana Anda menjembatani?", opts:[{t:"Memfasilitasi pembukaan rekening kolektif/didampingi, edukasi sederhana, dan menyiapkan jalur tunai terbatas bagi yang benar-benar tidak bisa", s:5},{t:"Memaksa semua lewat digital", s:4},{t:"Tetap tunai seperti biasa", s:3},{t:"Membiarkan yang tidak bisa tidak menerima", s:2},{t:"Menganggap digitalisasi gagal", s:1}], ex:"Skor 5 terbaik: transisi inklusif — didampingi menuju digital dengan jaring pengaman tunai bagi yang belum bisa."},
{id:"TKP-1239", q:"Listrik padam total di lokasi bencana sehingga semua perangkat digital mati. Data penting tersimpan di laptop yang baterainya habis. Apa yang Anda lakukan?", opts:[{t:"Mengaktifkan protokol darurat: catat manual terstruktur, amankan perangkat, cari sumber daya (genset/power bank), dan sinkronkan data setelah pulih", s:5},{t:"Mencatat manual seadanya", s:4},{t:"Berhenti bekerja sampai listrik menyala", s:3},{t:"Menganggap data hilang", s:2},{t:"Panik dan tidak tahu berbuat apa", s:1}], ex:"Skor 5 terbaik: protokol darurat berlapis (manual terstruktur + amankan perangkat + cari daya) menjaga data dan layanan."},
{id:"TKP-1240", q:"Sinyal seluler hilang di lokasi gempa. Koordinasi tim lumpuh. Ada radio komunikasi tetapi terbatas. Bagaimana Anda mengatur komunikasi?", opts:[{t:"Menyusun sistem komunikasi berjenjang via radio (jadwal check-in, kode pesan penting) plus kurir untuk pesan kritis", s:5},{t:"Menggunakan radio seadanya", s:4},{t:"Menunggu sinyal kembali", s:3},{t:"Berkoordinasi dengan bertemu langsung saja", s:2},{t:"Berhenti berkoordinasi", s:1}], ex:"Skor 5 terbaik: sistem komunikasi darurat yang terstruktur (jadwal + kode + kurir) menggantikan ketergantungan pada sinyal."},
{id:"TKP-1241", q:"Website informasi bencana daerah jarang diupdate sehingga warga mencari info ke sumber tidak resmi. Banyak info simpang siur. Apa yang Anda lakukan?", opts:[{t:"Mengusulkan dan mengelola update berkala website resmi (status bencana, kebutuhan, kontak) serta mempromosikannya sebagai sumber utama", s:5},{t:"Mengupdate sesekali", s:4},{t:"Membiarkan seperti apa adanya", s:3},{t:"Menutup website", s:2},{t:"Menganggap website tidak penting", s:1}], ex:"Skor 5 terbaik: kanal resmi yang aktif dan dipromosikan menjadi rujukan warga — memutus ketergantungan pada info simpang siur."},
{id:"TKP-1242", q:"Akun media sosial resmi posko ingin menyiarkan update kebutuhan (popok bayi kurang, obat menipis) agar donatur tepat membantu. Namun ada yang khawatir terlihat 'mengemis'. Sikap Anda?", opts:[{t:"Mendukung dengan format profesional dan transparan: daftar kebutuhan spesifik, update penyaluran, dan ucapan terima kasih", s:5},{t:"Mendukung seadanya", s:4},{t:"Melarang karena menjaga citra", s:3},{t:"Membiarkan admin memutuskan sendiri", s:2},{t:"Membuat drama agar viral", s:1}], ex:"Skor 5 terbaik: komunikasi kebutuhan yang profesional dan transparan justru membangun kepercayaan donatur."},
{id:"TKP-1243", q:"Beredar video lama banjir tahun lalu yang diklaim sebagai kondisi terkini untuk menggalang donasi bodong. Warga resah. Tindakan Anda?", opts:[{t:"Memverifikasi dan mempublikasikan fakta (video lama), melaporkan akun penyebar ke platform/aparat, dan mengedukasi warga", s:5},{t:"Mengumumkan bahwa video itu lama", s:4},{t:"Mengabaikan", s:3},{t:"Ikut menyebarkan agar waspada", s:2},{t:"Menganggap bukan urusan posko", s:1}], ex:"Skor 5 terbaik: verifikasi + publikasi fakta + pelaporan + edukasi — respons lengkap terhadap manipulasi informasi."},
{id:"TKP-1244", q:"Dinas ingin warga melaporkan kerusakan rumah lewat aplikasi, tetapi banyak warga tidak bisa menggunakannya. Laporan yang masuk sedikit. Solusi Anda?", opts:[{t:"Membuat pendampingan (posko bantuan aplikasi, tutorial sederhana) plus jalur lapor alternatif (RT, SMS, datang langsung)", s:5},{t:"Menyediakan tutorial tertulis", s:4},{t:"Memaksa lewat aplikasi saja", s:3},{t:"Membatalkan aplikasi", s:2},{t:"Menganggap warga malas", s:1}], ex:"Skor 5 terbaik: multi-jalur pelaporan yang inklusif — digitalisasi tidak meninggalkan yang gagap teknologi."},
{id:"TKP-1245", q:"Database relawan digital belum ada sehingga sulit menghubungi relawan terlatih saat bencana susulan terjadi. Apa yang Anda lakukan?", opts:[{t:"Membangun database relawan (data diri, keterampilan, kontak) dan sistem panggilan cepat yang terupdate berkala", s:5},{t:"Mencatat daftar relawan seadanya", s:4},{t:"Mengandalkan grup chat lama", s:3},{t:"Mencari relawan baru setiap bencana", s:2},{t:"Menganggap tidak perlu", s:1}], ex:"Skor 5 terbaik: database terstruktur plus sistem panggilan cepat membuat respons bencana susulan jauh lebih sigap."},
{id:"TKP-1246", q:"Pembagian sembako dengan antrean manual selalu ricuh. Ada usulan sistem antrean digital (nomor via SMS/aplikasi), tetapi khawatir warga tidak paham. Sikap Anda?", opts:[{t:"Menerapkan sistem hybrid: nomor antre digital didampingi petugas plus jalur manual bagi yang tidak bisa, disosialisasikan dulu", s:5},{t:"Menerapkan digital penuh", s:4},{t:"Tetap manual seperti biasa", s:3},{t:"Membatalkan usulan", s:2},{t:"Membiarkan kericuhan", s:1}], ex:"Skor 5 terbaik: hybrid inklusif — ketertiban digital tanpa mengorbankan yang belum melek teknologi."},
{id:"TKP-1247", q:"Beredar pesan phishing mengatasnamakan donasi bencana meminta transfer ke rekening pribadi. Beberapa warga sudah tertipu. Tindakan Anda?", opts:[{t:"Segera mengumumkan peringatan resmi, melaporkan rekening pelaku ke bank/aparat, dan mengedukasi warga cara verifikasi donasi resmi", s:5},{t:"Mengumumkan peringatan", s:4},{t:"Menyarankan korban melapor polisi", s:3},{t:"Mengabaikan karena di luar posko", s:2},{t:"Menganggap korban kurang hati-hati", s:1}], ex:"Skor 5 terbaik: peringatan + pelaporan + edukasi verifikasi melindungi warga dari penipuan berkedok kemanusiaan."},
{id:"TKP-1248", q:"Dokumentasi kegiatan posko akan dipublikasikan, tetapi banyak foto menampilkan wajah anak-anak pengungsi tanpa izin. Apa yang Anda lakukan?", opts:[{t:"Menyeleksi foto (blur wajah anak/tanpa identitas), meminta izin tertulis orang tua, dan menerapkan etika publikasi", s:5},{t:"Meminta izin orang tua dulu", s:4},{t:"Mempublikasikan seadanya", s:3},{t:"Mempublikasikan semua", s:2},{t:"Menganggap publikasi lebih penting", s:1}], ex:"Skor 5 terbaik: perlindungan anak di ruang digital — izin plus anonimisasi sebelum publikasi."},
{id:"TKP-1249", q:"Posko memasang CCTV untuk keamanan logistik, tetapi sebagian pengungsi merasa diawasi dan tidak nyaman. Bagaimana Anda menyikapi?", opts:[{t:"Menjelaskan tujuan CCTV (keamanan bersama), memasang hanya di area logistik (bukan area privat), dan memasang pemberitahuan", s:5},{t:"Menjelaskan tujuannya", s:4},{t:"Mencopot semua CCTV", s:3},{t:"Membiarkan tanpa penjelasan", s:2},{t:"Menambah CCTV di mana-mana", s:1}], ex:"Skor 5 terbaik: transparansi tujuan + penempatan proporsional menyeimbangkan keamanan dan kenyamanan."},
{id:"TKP-1250", q:"Pimpinan meminta survei kepuasan pengungsi secara digital untuk evaluasi, tetapi respons rendah karena pengungsi sibuk dan lelah. Bagaimana Anda mendapatkan umpan balik yang valid?", opts:[{t:"Menggabungkan survei singkat digital dengan wawancara langsung santai oleh petugas, di waktu yang tepat dan tidak membebani", s:5},{t:"Memaksa pengungsi mengisi survei", s:4},{t:"Mengirim link survei saja", s:3},{t:"Membuat data survei perkiraan", s:2},{t:"Tidak melakukan survei", s:1}], ex:"Skor 5 terbaik: kombinasi metode yang empatik menghasilkan umpan balik valid tanpa membebani korban."},
{id:"TKP-1251", q:"Beredar propaganda bahwa bencana yang terjadi adalah 'azab' untuk kelompok agama tertentu. Ujaran ini memecah belah pengungsi. Bagaimana Anda menangkalnya?", opts:[{t:"Menegaskan bencana adalah musibah kemanusiaan bagi semua, mengajak tokoh lintas agama menyerukan persatuan, dan menindak penyebar ujaran kebencian", s:5},{t:"Mengimbau warga tidak percaya propaganda", s:4},{t:"Membiarkan karena pendapat pribadi", s:3},{t:"Ikut menyebarkan", s:2},{t:"Membenarkan propaganda itu", s:1}], ex:"Skor 5 terbaik: narasi persatuan lintas tokoh agama plus penindakan penyebar — bencana mempersatukan, bukan memecah."},
{id:"TKP-1252", q:"Ujaran kebencian terhadap pengungsi dari kelompok agama minoritas beredar di media sosial warga sekitar posko. Ketegangan meningkat. Tindakan Anda?", opts:[{t:"Berkoordinasi dengan aparat dan tokoh masyarakat untuk meredam, mengedukasi, dan menindak penyebar ujaran kebencian sesuai hukum", s:5},{t:"Mengimbau warga menjaga kerukunan", s:4},{t:"Membiarkan karena kebebasan berpendapat", s:3},{t:"Memindahkan pengungsi minoritas", s:2},{t:"Ikut memusuhi", s:1}], ex:"Skor 5 terbaik: redam + edukasi + penindakan hukum — ujaran kebencian bukan kebebasan berpendapat."},
{id:"TKP-1253", q:"Kelompok intoleran mendatangi posko menolak kehadiran pengungsi yang berbeda keyakinan dan menuntut mereka dipindah. Situasi tegang. Sikap Anda?", opts:[{t:"Menegaskan posko melayani semua warga negara tanpa diskriminasi, berdialog dengan kelompok tersebut, dan melibatkan aparat bila mengancam", s:5},{t:"Berdialog mencari pengertian", s:4},{t:"Memindahkan pengungsi agar aman", s:3},{t:"Menuruti tuntutan kelompok intoleran", s:2},{t:"Ikut mengusir", s:1}], ex:"Skor 5 terbaik: prinsip non-diskriminasi ditegakkan dengan dialog; aparat dilibatkan bila ada ancaman — tidak tunduk pada intoleransi."},
{id:"TKP-1254", q:"Seorang penceramah di pengungsian menyampaikan ceramah provokatif yang menyudutkan kelompok lain dan mengajak permusuhan. Jemaah terpengaruh. Apa yang Anda lakukan?", opts:[{t:"Berkoordinasi dengan tokoh agama moderat untuk penyeimbang, menegur penceramah, dan memastikan kegiatan keagamaan menyejukkan", s:5},{t:"Menegur penceramah tersebut", s:4},{t:"Membiarkan karena kebebasan berdakwah", s:3},{t:"Melarang semua ceramah", s:2},{t:"Ikut terprovokasi", s:1}], ex:"Skor 5 terbaik: penyeimbang moderat + teguran — ruang keagamaan di pengungsian harus menyejukkan, bukan memanas."},
{id:"TKP-1255", q:"Kelompok ekstrem menawarkan bantuan besar ke pengungsi dengan syarat mengikuti kajian ideologi mereka. Pengungsi yang putus asa mulai tertarik. Bagaimana Anda mencegah?", opts:[{t:"Memastikan kebutuhan dasar pengungsi terpenuhi lewat jalur resmi, mengedukasi bahaya infiltrasi ideologi, dan melaporkan kelompok tersebut", s:5},{t:"Melarang pengungsi menerima bantuan itu", s:4},{t:"Membiarkan karena bantuan tetap bantuan", s:3},{t:"Ikut menghadiri kajiannya", s:2},{t:"Mendukung kelompok tersebut", s:1}], ex:"Skor 5 terbaik: penuhi kebutuhan (hilangkan kerentanan) + edukasi + laporkan — memutus rekrutmen di akarnya."},
{id:"TKP-1256", q:"Ditemukan selebaran berisi ajakan radikal di area posko pengungsian. Beberapa pengungsi sudah membacanya. Tindakan Anda?", opts:[{t:"Mengamankan selebaran, melaporkan ke aparat/BNPT, dan memberi penjelasan penyeimbang kepada pengungsi", s:5},{t:"Membuang selebaran tersebut", s:4},{t:"Mengabaikan", s:3},{t:"Menyebarkan ke grup untuk kewaspadaan", s:2},{t:"Ikut membagikan", s:1}], ex:"Skor 5 terbaik: amankan barang bukti + lapor aparat + edukasi — penanganan sistematis, bukan sekadar dibuang."},
{id:"TKP-1257", q:"Beredar narasi bahwa pemerintah sengaja menelantarkan korban bencana di daerah tertentu karena alasan politik. Narasi ini viral dan memicu kemarahan. Bagaimana Anda menangkal?", opts:[{t:"Membuka data penanganan secara transparan (distribusi, anggaran, jadwal), mengajak warga memverifikasi langsung, dan klarifikasi resmi", s:5},{t:"Membantah narasi tersebut", s:4},{t:"Mengabaikan", s:3},{t:"Menyalahkan oposisi", s:2},{t:"Membenarkan kemarahan warga", s:1}], ex:"Skor 5 terbaik: transparansi data yang bisa diverifikasi adalah penangkal paling ampuh narasi politik destruktif."},
{id:"TKP-1258", q:"Relawan yang membantu di posko mengenakan simbol kelompok ekstrem dan menyebarkannya diam-diam ke pengungsi muda. Anda mengetahuinya. Tindakan Anda?", opts:[{t:"Mengeluarkannya dari tim relawan, melaporkan ke aparat, dan memastikan proses rekrutmen relawan diperketat", s:5},{t:"Menegur dan memintanya melepas simbol", s:4},{t:"Membiarkan karena tenaganya dibutuhkan", s:3},{t:"Mengabaikan", s:2},{t:"Ikut memakai simbol", s:1}], ex:"Skor 5 terbaik: ruang kemanusiaan harus steril dari infiltrasi ekstrem; keluarkan, laporkan, perketat rekrutmen."},
{id:"TKP-1259", q:"Konten media sosial menyalahkan satu kelompok agama sebagai penyebab bencana dan mengajak boikot bantuan untuk mereka. Kontennya viral. Apa yang Anda lakukan?", opts:[{t:"Melaporkan konten tersebut, membuat kontra-narasi persatuan bersama tokoh lintas agama, dan memastikan bantuan tetap untuk semua", s:5},{t:"Melaporkan kontennya", s:4},{t:"Mengabaikan", s:3},{t:"Ikut menyebarkan boikot", s:2},{t:"Membenarkan kontennya", s:1}], ex:"Skor 5 terbaik: laporkan + kontra-narasi persatuan + jaminan bantuan non-diskriminatif — tiga lapis pertahanan."},
{id:"TKP-1260", q:"Untuk memperkuat persatuan pasca-bencana, Anda diminta membuat kegiatan bersama di pengungsian yang melibatkan semua latar belakang. Apa konsep terbaik?", opts:[{t:"Gotong royong membangun fasilitas bersama + pentas seni budaya lintas daerah + doa bersama lintas agama — merayakan kebersamaan dalam keberagaman", s:5},{t:"Acara hiburan bersama", s:4},{t:"Kegiatan untuk kelompok mayoritas saja", s:3},{t:"Tidak membuat kegiatan", s:2},{t:"Kegiatan yang memisah tiap kelompok", s:1}], ex:"Skor 5 terbaik: kegiatan kolaboratif lintas latar merawat persatuan sebagai modal pemulihan jangka panjang."},
];
